import React, { useState, useEffect, useMemo, useCallback } from "react";

// ---------------------------------------------------------------------------
// QUESTION BANK
// id | c = category | d = difficulty | q = question | a = answer | t = trap/tip
// ---------------------------------------------------------------------------

const QUESTIONS = [
  // ======================= JAVASCRIPT & TYPESCRIPT =========================
  { id: "js1", c: "JavaScript & TS", d: "Easy", q: `Explain the difference between var, let and const.`, a: `var is function-scoped, hoisted and initialised to undefined, and can be redeclared. let and const are block-scoped and hoisted but sit in the Temporal Dead Zone until the declaration line, so reading them early throws a ReferenceError. const prevents rebinding of the identifier, not mutation of the value: a const object can still have its properties changed.`, t: `Interviewers usually follow up with "is const immutable?" — say no, only the binding is.` },
  { id: "js2", c: "JavaScript & TS", d: "Easy", q: `What is hoisting, and what exactly gets hoisted?`, a: `During the creation phase of an execution context the engine registers declarations in memory before running any code. Function declarations are hoisted with their body. var declarations are hoisted and initialised to undefined. let, const and class are hoisted but uninitialised (TDZ). Function expressions and arrow functions follow the rules of the variable they are assigned to.` },
  { id: "js3", c: "JavaScript & TS", d: "Medium", q: `Explain closures with a practical use case.`, a: `A closure is a function bundled with a reference to its lexical environment, so it keeps access to outer variables after the outer function has returned. Practical uses: data privacy (module pattern, counters), function factories, memoisation caches, once() wrappers, and every React hook that captures props/state in a callback.`, t: `Be ready to explain the classic for-loop with var printing 3,3,3 and why let fixes it (new binding per iteration).` },
  { id: "js4", c: "JavaScript & TS", d: "Medium", q: `How does the "this" keyword resolve in JavaScript?`, a: `Resolution order: (1) new binding — this is the newly constructed object; (2) explicit binding via call/apply/bind; (3) implicit binding — the object left of the dot at call time; (4) default binding — undefined in strict mode, globalThis otherwise. Arrow functions have no own this; they inherit it lexically, which is why they cannot be used as constructors or have their this rebound.` },
  { id: "js5", c: "JavaScript & TS", d: "Medium", q: `Explain the event loop, call stack, microtasks and macrotasks.`, a: `Synchronous code runs on the call stack. When the stack empties, the event loop drains the entire microtask queue (promise callbacks, queueMicrotask, MutationObserver), then runs one macrotask (setTimeout, setInterval, I/O, UI events), then drains microtasks again. So promises always resolve before a setTimeout(0) scheduled at the same moment, and an infinite microtask chain can starve rendering.`, t: `Expect an ordering puzzle mixing console.log, setTimeout, Promise.resolve().then and async/await.` },
  { id: "js6", c: "JavaScript & TS", d: "Hard", q: `In Node, where do process.nextTick and setImmediate fit in the loop?`, a: `Node has extra queues. process.nextTick has higher priority than promise microtasks and is drained after the current operation completes, before the loop continues. setImmediate runs in the check phase, after the poll phase. Inside an I/O callback setImmediate always fires before setTimeout(0); at the top level the order between them is non-deterministic because it depends on how long the process took to boot.` },
  { id: "js7", c: "JavaScript & TS", d: "Medium", q: `What is the prototype chain and how does class inheritance map onto it?`, a: `Every object has an internal [[Prototype]] link (exposed as __proto__ / Object.getPrototypeOf). Property lookup walks that chain until it finds the key or hits null. A function's .prototype object becomes the [[Prototype]] of instances created with new. class is syntactic sugar over this: extends sets up the chain and super() calls the parent constructor.` },
  { id: "js8", c: "JavaScript & TS", d: "Easy", q: `Difference between == and ===, and when is == acceptable?`, a: `=== compares type and value with no coercion. == applies the abstract equality algorithm, coercing across types. The one widely accepted use of == is x == null, which is true for both null and undefined and false for everything else.` },
  { id: "js9", c: "JavaScript & TS", d: "Medium", q: `Explain shallow vs deep copy and the ways to deep clone.`, a: `Spread and Object.assign copy only one level; nested objects stay shared by reference. Deep clone options: structuredClone (native, handles Date, Map, Set, cyclic refs, but not functions), JSON.parse(JSON.stringify(x)) (loses undefined, functions, Dates become strings, throws on cycles), or lodash cloneDeep.` },
  { id: "js10", c: "JavaScript & TS", d: "Medium", q: `Implement debounce and explain where it differs from throttle.`, a: `Debounce delays execution until N ms have passed with no new calls — good for search-as-you-type and resize handlers. Throttle guarantees at most one call per N ms — good for scroll position, mousemove, infinite scroll. Implementation: keep a timer id in a closure; debounce clears and resets it on every call, throttle ignores calls while a cooldown flag is set.`, t: `They often ask you to add a cancel() method and a leading/trailing option.` },
  { id: "js11", c: "JavaScript & TS", d: "Medium", q: `What do call, apply and bind do?`, a: `call invokes immediately with an explicit this and comma-separated args. apply is the same but takes an array of args. bind returns a new function permanently bound to that this, with optional partial application. A bound function cannot be rebound, but new still overrides the bound this.` },
  { id: "js12", c: "JavaScript & TS", d: "Hard", q: `Explain how async/await works under the hood.`, a: `An async function returns a promise and is compiled to a state machine over generators. await suspends the function, registers a continuation as a promise microtask, and returns control to the caller. On resolution the continuation resumes with the value; on rejection it throws at the await point, so try/catch works. Sequential awaits are serial — use Promise.all when the operations are independent.` },
  { id: "js13", c: "JavaScript & TS", d: "Medium", q: `Compare Promise.all, allSettled, race and any.`, a: `all rejects fast on the first rejection and otherwise resolves with an ordered array. allSettled never rejects and returns status/value/reason objects — best for dashboards and batch jobs. race settles with the first settled promise, resolved or rejected — used for timeouts. any resolves with the first fulfilled promise and rejects with an AggregateError only if all reject.` },
  { id: "js14", c: "JavaScript & TS", d: "Medium", q: `What are generators and where would you actually use one?`, a: `A function* can pause at yield and resume with a value passed into next(). Real uses: lazy or infinite sequences, cursor-style pagination over a large API, custom iterables, and cooperative cancellation. Redux-Saga is built on them, and async/await is generators plus a promise-driven runner.` },
  { id: "js15", c: "JavaScript & TS", d: "Easy", q: `What is the difference between null and undefined?`, a: `undefined means a variable exists but has no assigned value — the engine produces it. null is an explicit, developer-assigned "no value". typeof undefined is "undefined"; typeof null is "object", a long-standing bug kept for compatibility.` },
  { id: "js16", c: "JavaScript & TS", d: "Medium", q: `Explain optional chaining and nullish coalescing, and the bug ?? prevents.`, a: `a?.b?.c short-circuits to undefined instead of throwing on a null/undefined link. ?? falls back only for null and undefined, whereas || also falls back for 0, "" and false. Using || for a default count or a boolean flag silently discards legitimate falsy values.` },
  { id: "js17", c: "JavaScript & TS", d: "Medium", q: `How does the JS module system differ between ESM and CommonJS?`, a: `CommonJS uses require/module.exports, is loaded synchronously, resolves at runtime, and gives you a copy of the exported value. ESM uses import/export, is statically analysable (enabling tree shaking), is hoisted, supports top-level await, and gives live bindings. In Node you opt in with "type": "module" or the .mjs extension; mixing them causes most of the ERR_REQUIRE_ESM pain.` },
  { id: "js18", c: "JavaScript & TS", d: "Hard", q: `What is the difference between Map/Set and plain objects/arrays?`, a: `Map allows any key type including objects, preserves insertion order, has O(1) size, and does not collide with prototype keys. Set gives O(1) membership tests versus Array.includes at O(n). WeakMap/WeakSet hold keys weakly so entries are garbage collected when the key is unreachable — useful for caching metadata against DOM nodes or objects without leaking.` },
  { id: "js19", c: "JavaScript & TS", d: "Medium", q: `What causes memory leaks in JavaScript applications?`, a: `Common causes: listeners and intervals never cleaned up, detached DOM nodes still referenced by JS, closures holding large objects, growing global caches with no eviction, and in React, setState after unmount or subscriptions without a cleanup return. Diagnose with Chrome DevTools heap snapshots and the allocation timeline, comparing retained size across snapshots.` },
  { id: "js20", c: "JavaScript & TS", d: "Medium", q: `Explain currying and partial application.`, a: `Currying transforms f(a,b,c) into f(a)(b)(c) — each call takes exactly one argument and returns a function. Partial application fixes some arguments and returns a function taking the rest. Both are built on closures; bind is partial application built into the language.` },
  { id: "js21", c: "JavaScript & TS", d: "Hard", q: `Implement Promise.all yourself.`, a: `Return a new Promise. Track a results array of the same length and a resolvedCount. Iterate the input, wrap each entry in Promise.resolve, and on fulfilment write the value at its original index and increment the counter; resolve when the counter matches the length. Reject immediately on any rejection. Handle the empty-array case by resolving straight away.` },
  { id: "js22", c: "JavaScript & TS", d: "Medium", q: `What is event delegation and why use it?`, a: `Attach one listener on a common ancestor and use event.target plus closest() to identify the source, relying on bubbling. It reduces listener count on large lists, works automatically for elements added later, and cuts memory. Watch out for events that do not bubble (focus, blur — use focusin/focusout) and for stopPropagation upstream.` },
  { id: "js23", c: "JavaScript & TS", d: "Medium", q: `Explain TypeScript interface vs type alias.`, a: `interface supports declaration merging and is idiomatic for object shapes and public API contracts. type can express unions, intersections, tuples, mapped and conditional types, and primitives. Practical rule: interface for object contracts you might extend, type for everything algebraic.` },
  { id: "js24", c: "JavaScript & TS", d: "Medium", q: `What are generics in TypeScript and why do they matter?`, a: `Generics parameterise types so a function or component preserves the relationship between input and output instead of collapsing to any. Example: a useFetch<T> hook returns data typed as T. Constraints (T extends { id: string }) let you require capabilities while staying generic.` },
  { id: "js25", c: "JavaScript & TS", d: "Hard", q: `Explain unknown vs any vs never.`, a: `any disables type checking and is contagious. unknown is the type-safe top type — you can assign anything to it but must narrow before using it. never is the bottom type: no value inhabits it. never is what you get in an exhaustive switch default, which is how you make the compiler fail when a new union member is added.` },
  { id: "js26", c: "JavaScript & TS", d: "Hard", q: `What are utility types like Partial, Pick, Omit, Record built on?`, a: `Mapped types plus keyof. Partial<T> maps every key to optional, Required removes optionals, Pick selects keys, Omit is Pick<T, Exclude<keyof T, K>>, Record<K,V> builds an object type from a key union. Knowing they are mapped types lets you write your own, e.g. a DeepPartial with recursion.` },
  { id: "js27", c: "JavaScript & TS", d: "Medium", q: `How do type guards and discriminated unions work?`, a: `A discriminated union gives each member a literal tag field, so switching on that tag narrows the type in each branch. Custom guards use the predicate signature isUser(x: unknown): x is User. typeof, instanceof and the in operator also narrow. This is the main tool for handling API responses that vary by status.` },
  { id: "js28", c: "JavaScript & TS", d: "Easy", q: `What does the spread and rest syntax do, and where do they differ?`, a: `Same three dots, opposite direction. Spread expands an iterable or object into individual elements/properties (copying, merging, passing args). Rest collects remaining items into an array or object (function params, destructuring). Object spread is a shallow copy.` },
  { id: "js29", c: "JavaScript & TS", d: "Medium", q: `Explain how JavaScript handles numbers and why 0.1 + 0.2 !== 0.3.`, a: `All numbers are IEEE-754 doubles, so 0.1 and 0.2 have no exact binary representation and the sum lands slightly above 0.3. Compare with an epsilon, or for money use integer minor units (paise/cents) or a decimal library. Integers above Number.MAX_SAFE_INTEGER lose precision — use BigInt.`, t: `As a fintech engineer, mention storing amounts in minor units — it lands well.` },
  { id: "js30", c: "JavaScript & TS", d: "Hard", q: `What is the difference between structuredClone-able data and transferables in workers?`, a: `postMessage uses the structured clone algorithm, which copies data (cost proportional to size) and cannot carry functions or DOM nodes. Transferable objects like ArrayBuffer, MessagePort and OffscreenCanvas can be moved with zero copy, but the sender loses access. SharedArrayBuffer allows real shared memory but requires cross-origin isolation headers.` },
  { id: "js31", c: "JavaScript & TS", d: "Medium", q: `How does garbage collection work in V8?`, a: `V8 uses a generational mark-and-sweep collector. New objects go into a small young generation collected frequently with a cheap scavenger; survivors are promoted to the old generation, collected with mark-sweep-compact and largely concurrent/incremental to reduce pauses. Anything reachable from the roots survives — reachability, not scope exit, decides.` },
  { id: "js32", c: "JavaScript & TS", d: "Medium", q: `What are Symbols used for?`, a: `Unique, non-enumerable property keys that never collide, used for metadata on objects you do not own. Well-known symbols hook into language behaviour: Symbol.iterator makes an object usable in for...of and spread, Symbol.asyncIterator powers for await...of, Symbol.toPrimitive controls coercion.` },
  { id: "js33", c: "JavaScript & TS", d: "Hard", q: `Explain Proxy and Reflect with a real use case.`, a: `A Proxy wraps a target and intercepts fundamental operations through traps (get, set, has, deleteProperty). Reflect provides the default implementations so traps can forward correctly. Real uses: Vue 3 reactivity, validation layers, negative array indices, and mocking in tests. Cost: proxies are slower than plain property access on hot paths.` },
  { id: "js34", c: "JavaScript & TS", d: "Easy", q: `What is the difference between forEach, map, filter, reduce?`, a: `forEach iterates for side effects and returns undefined, and cannot be broken out of early. map returns a new array of the same length. filter returns a subset. reduce folds to a single value of any shape. For early exit use for...of, some or find.` },
  { id: "js35", c: "JavaScript & TS", d: "Medium", q: `How do you handle errors properly in async code?`, a: `Wrap awaits in try/catch, and always attach a catch to floating promises or Node will crash on unhandledRejection in modern versions. In Express, async route handlers need a wrapper that forwards rejections to next(). Preserve the original error with the cause option, and never swallow errors into an empty catch.` },
  { id: "js36", c: "JavaScript & TS", d: "Medium", q: `What is an IIFE and is it still relevant?`, a: `An immediately invoked function expression creates a private scope on the spot. It was the pre-ES6 module pattern. Today block scoping and ES modules cover most cases, but IIFEs still appear for top-level await in CommonJS, for one-off initialisation, and in bundled library output.` },
  { id: "js37", c: "JavaScript & TS", d: "Hard", q: `Explain tail calls, recursion limits and how to avoid stack overflow.`, a: `JS engines other than JavaScriptCore do not implement proper tail-call optimisation, so deep recursion overflows the stack. Convert to iteration with an explicit stack, use trampolining (return a thunk and loop), or chunk work across microtasks/setTimeout so the stack unwinds between batches.` },
  { id: "js38", c: "JavaScript & TS", d: "Medium", q: `What does "use strict" change?`, a: `It makes silent errors throw: assigning to undeclared variables, writing to read-only or non-writable properties, duplicate parameter names. It sets this to undefined in default binding, forbids with and octal literals, and makes eval scope isolated. ES modules and class bodies are always strict.` },
  { id: "js39", c: "JavaScript & TS", d: "Medium", q: `How would you type an API response safely at runtime in TypeScript?`, a: `TypeScript types vanish at runtime, so a cast lies to you if the API drifts. Validate at the boundary with Zod, Valibot or io-ts and infer the static type from the schema — one source of truth, real runtime errors instead of undefined-is-not-a-function deep in a component.`, t: `Strong answer for a 2-year candidate: name the boundary-validation pattern explicitly.` },
  { id: "js40", c: "JavaScript & TS", d: "Hard", q: `What is the difference between a shallow-equal check and a deep-equal check in hot paths?`, a: `Shallow equality compares references for object values — O(number of keys), which is why React memo, useMemo deps and Redux selectors rely on it and why creating a new object literal every render defeats them. Deep equality walks the whole structure and gets expensive; if you need it in a hot path, prefer normalising data or using stable identities/keys instead.` },

  // ================================ REACT ==================================
  { id: "re1", c: "React", d: "Easy", q: `What is the virtual DOM and how does reconciliation work?`, a: `React keeps a lightweight tree of elements in memory. On a state change it builds a new tree and diffs it against the old one using heuristics: different element types replace the subtree, same type patches props, and lists are matched by key. Only the resulting minimal set of DOM mutations is committed.`, t: `Do not say "the virtual DOM is faster than the DOM" — say it batches and minimises DOM writes, which is what actually costs.` },
  { id: "re2", c: "React", d: "Easy", q: `Why do lists need keys, and why is the array index a bad key?`, a: `Keys tell React which element corresponds to which item across renders so it can move rather than recreate DOM and preserve component state. With index keys, inserting or reordering shifts every index, so React patches the wrong nodes — inputs keep the wrong values, animations glitch, and state attaches to the wrong row. Index keys are only safe for static, never-reordered lists.` },
  { id: "re3", c: "React", d: "Medium", q: `Explain the rules of hooks and why they exist.`, a: `Hooks must be called at the top level of a component or another hook, never inside conditions, loops or nested functions, and only from React functions. React stores hook state in an ordered list per fiber and matches calls to slots by call order, so a conditional hook shifts the whole list and corrupts state.` },
  { id: "re4", c: "React", d: "Medium", q: `useMemo vs useCallback vs React.memo — when does each actually help?`, a: `useMemo caches a computed value, useCallback caches a function identity, React.memo skips re-render when props are shallow-equal. They only pay off when the child is expensive or memoised, or the value feeds a dependency array. Wrapping everything adds allocation and comparison cost and hides real problems — profile first.`, t: `A common trap: memoising a component whose parent passes a new inline object or arrow function, which defeats the memo entirely.` },
  { id: "re5", c: "React", d: "Medium", q: `Explain useEffect: dependency array, cleanup and the common mistakes.`, a: `The effect runs after the commit. No array means every render, an empty array means once on mount, and dependencies mean whenever one changes by Object.is. The cleanup function runs before the next effect and on unmount — use it for listeners, timers, sockets and aborting fetches. Common mistakes: lying about dependencies, missing cleanup causing leaks, and using an effect for derived state that could be computed during render.` },
  { id: "re6", c: "React", d: "Medium", q: `useEffect vs useLayoutEffect — when do you need the layout one?`, a: `useLayoutEffect fires synchronously after DOM mutation but before the browser paints, so it blocks paint. Use it only when you must read layout (measure a node) and mutate synchronously to avoid a visible flicker — tooltips, scroll restoration, measuring for virtualisation. Everything else goes in useEffect. It also warns during SSR because there is no layout on the server.` },
  { id: "re7", c: "React", d: "Medium", q: `useState vs useReducer — how do you choose?`, a: `useState for independent, simple values. useReducer when the next state depends on the previous one in non-trivial ways, when several fields change together, or when you want state transitions to be testable as a pure function. It also lets you pass a stable dispatch down instead of many callbacks, which reduces prop churn.` },
  { id: "re8", c: "React", d: "Medium", q: `What is the Context API for and what is its main performance problem?`, a: `Context passes values down without prop drilling. The problem: every consumer re-renders when the context value changes by reference, so an object literal recreated each render re-renders the whole subtree. Fixes: memoise the value, split into separate contexts for state and dispatch, or move to a store with selector-based subscriptions (Zustand, Redux Toolkit, Jotai).` },
  { id: "re9", c: "React", d: "Hard", q: `What are controlled and uncontrolled components? Which do you use at scale?`, a: `Controlled inputs derive their value from state and update via onChange, so React is the single source of truth — needed for validation, formatting and conditional fields. Uncontrolled inputs keep value in the DOM and are read via a ref. For large forms, controlled-everything re-renders the whole form per keystroke, which is why React Hook Form uses uncontrolled inputs with refs and subscribes only the fields that need to re-render.` },
  { id: "re10", c: "React", d: "Medium", q: `What are custom hooks and what makes a good one?`, a: `A function starting with use that composes other hooks to share stateful logic (not UI). A good one has a single responsibility, a stable return shape, handles its own cleanup, and does not secretly depend on where it is mounted. Each call gets its own isolated state — hooks share logic, not state.` },
  { id: "re11", c: "React", d: "Hard", q: `Explain React fiber, and what concurrent rendering changed.`, a: `Fiber restructured reconciliation into interruptible units of work with a render phase (can pause, abort, restart, must be pure) and a commit phase (synchronous, applies DOM changes). Concurrent rendering lets React keep a lower-priority render in progress while urgent updates jump ahead, which is what powers useTransition, useDeferredValue and Suspense streaming.` },
  { id: "re12", c: "React", d: "Hard", q: `What do useTransition and useDeferredValue do?`, a: `useTransition marks an update as non-urgent, returning isPending plus a startTransition wrapper — the typed input stays responsive while an expensive filtered list renders in the background. useDeferredValue takes a value and returns a lagging copy, which is useful when you do not own the setter. Both prevent input lag; neither makes the expensive work cheaper.` },
  { id: "re13", c: "React", d: "Medium", q: `How do you handle errors in React? What are error boundaries?`, a: `A class component with getDerivedStateFromError and/or componentDidCatch catches render, lifecycle and constructor errors below it and renders a fallback. They do not catch event handlers, async code, SSR or errors in the boundary itself — those need try/catch or a global handler. react-error-boundary provides a hook-friendly wrapper with a reset key.` },
  { id: "re14", c: "React", d: "Medium", q: `What is React Suspense and how does data fetching use it?`, a: `Suspense declares a fallback for a subtree that is not ready. React.lazy uses it for code splitting. For data, a resource throws a promise (or in RSC the framework awaits) and React shows the fallback until it resolves, enabling streaming SSR where the shell flushes first. Libraries like React Query and Relay opt into it rather than you writing throw-a-promise by hand.` },
  { id: "re15", c: "React", d: "Medium", q: `Explain refs: useRef, forwardRef, useImperativeHandle.`, a: `useRef gives a mutable box whose .current persists across renders without triggering one — for DOM nodes, timer ids, previous values and instance-like data. forwardRef lets a parent attach a ref to a DOM node inside a child component. useImperativeHandle narrows what the parent can call on that ref (focus, reset) instead of exposing the raw node. In React 19, ref is a normal prop and forwardRef is no longer required.` },
  { id: "re16", c: "React", d: "Medium", q: `How does React batch state updates?`, a: `React 18 batches automatically everywhere — event handlers, promises, timeouts, native handlers — so multiple setState calls in one tick produce one re-render. Use the functional updater when the next value depends on the previous one, otherwise stale closures give you a lost update. flushSync forces a synchronous render but costs performance.` },
  { id: "re17", c: "React", d: "Hard", q: `What causes stale closures in React and how do you fix them?`, a: `A callback captures the props/state from the render it was created in. If it is stored in a ref, a subscription or an interval created once with an empty dep array, it keeps reading old values. Fixes: include the dependency and recreate the callback, use the functional setState form, or keep the latest callback in a ref updated on every render (the "latest ref" pattern).` },
  { id: "re18", c: "React", d: "Medium", q: `How do you render very large lists efficiently?`, a: `Virtualise with react-window or TanStack Virtual so only visible rows plus an overscan buffer mount. Combine with stable keys, memoised row components, avoiding inline objects in props, pagination or infinite scroll on the server side, and content-visibility CSS for cheap wins. Measure with the Profiler before and after.` },
  { id: "re19", c: "React", d: "Medium", q: `Explain code splitting in React and where to split.`, a: `React.lazy plus Suspense splits at the component level; bundlers turn dynamic import() into separate chunks. Split at route boundaries first, then at heavy widgets (charts, editors, PDF viewers) and modals. Preload on hover or intent to hide the network cost, and keep an eye on waterfalls from nested lazy boundaries.` },
  { id: "re20", c: "React", d: "Medium", q: `How would you manage server state vs client state?`, a: `Server state is asynchronous, shared, and can go stale — it belongs in a cache like React Query or SWR that handles deduping, background refetch, retries, pagination and invalidation. Client state (modals, form drafts, filters) belongs in local state, context or a small store. Putting server data into Redux by hand recreates a worse cache.`, t: `Saying this clearly separates a 2-year candidate from a 6-month one.` },
  { id: "re21", c: "React", d: "Medium", q: `Explain Redux Toolkit core concepts.`, a: `configureStore wires the store with sensible middleware and devtools. createSlice generates reducers and action creators together, using Immer so you write mutating syntax that produces immutable updates. createAsyncThunk handles pending/fulfilled/rejected. RTK Query adds a full data-fetching cache with tag-based invalidation. Selectors (reselect) memoise derived data.` },
  { id: "re22", c: "React", d: "Hard", q: `How do React Server Components differ from SSR?`, a: `SSR renders the same client components to HTML on the server and then hydrates them, shipping their JS. Server Components run only on the server, never hydrate, and ship zero JS for themselves — they can query a database directly and stream serialised output. They cannot use state, effects or browser APIs; interactive parts stay client components marked "use client".` },
  { id: "re23", c: "React", d: "Medium", q: `What is hydration and what causes hydration mismatch errors?`, a: `Hydration attaches event listeners and builds the fiber tree over server-rendered HTML, expecting identical markup. Mismatches come from Date.now(), Math.random(), locale or timezone formatting, reading window during render, browser extensions mutating the DOM, and invalid HTML nesting that the parser corrects. Fix by moving the non-deterministic bit into an effect or gating on a mounted flag.` },
  { id: "re24", c: "React", d: "Medium", q: `What is prop drilling and what are the alternatives?`, a: `Passing props through components that do not use them. Alternatives: composition and the children prop (often the cleanest and most overlooked), context for genuinely global values, or a store with selectors. Reaching for a global store as the first answer is a smell — composition solves many cases.` },
  { id: "re25", c: "React", d: "Medium", q: `How do you test React components?`, a: `React Testing Library with Jest or Vitest: query by role and accessible name, interact with userEvent, and assert on what the user sees rather than implementation details. Mock the network with MSW instead of stubbing fetch. Test custom hooks with renderHook. Reserve snapshots for small stable output; large snapshots get rubber-stamped.` },
  { id: "re26", c: "React", d: "Hard", q: `Explain useSyncExternalStore and why it exists.`, a: `It is the supported way to subscribe to a store outside React (browser APIs, Redux, a socket) while staying safe under concurrent rendering — you give it subscribe, getSnapshot and optionally getServerSnapshot. Without it, tearing can occur: two components read different values from the same store within one render pass.` },
  { id: "re27", c: "React", d: "Easy", q: `What is JSX and how does it compile?`, a: `JSX is syntax sugar compiled to React.createElement calls, or with the automatic runtime to jsx() imports from react/jsx-runtime. That is why props become an object, children become arguments, and expressions in braces are just JavaScript. It also explains why component names must be capitalised — lowercase compiles to a string tag.` },
  { id: "re28", c: "React", d: "Medium", q: `What are the main React 19 additions worth knowing?`, a: `Actions and useActionState for form submissions with built-in pending state, useOptimistic for optimistic UI, use() to read promises and context conditionally, ref as a plain prop, the React Compiler (auto-memoisation), document metadata hoisting, and improved async transition handling.` },
  { id: "re29", c: "React", d: "Medium", q: `How do you implement optimistic updates?`, a: `Apply the expected result to the cache immediately, keep the previous snapshot, fire the mutation, and roll back on failure. React Query does this with onMutate/onError/onSettled; React 19 offers useOptimistic. Key details: rollback on error, invalidate on settle to reconcile with the server, and guard against out-of-order responses.` },
  { id: "re30", c: "React", d: "Hard", q: `What is a render prop and how does it compare to hooks and HOCs?`, a: `A render prop passes a function as children to share logic while letting the caller control markup. HOCs wrap a component and inject props but cause wrapper hell, name collisions and ref forwarding pain. Hooks replaced most of both by sharing logic without changing the tree. Render props still shine when the shared logic must control rendering timing, as in virtualisation or drag libraries.` },
  { id: "re31", c: "React", d: "Medium", q: `How do you avoid unnecessary re-renders in a real app?`, a: `Move state down to the smallest subtree that needs it, lift expensive children into props/children so they are not recreated, memoise heavy leaves, stabilise callbacks and objects, split contexts, use selectors so a store change only wakes interested components, and keep list rows pure. Verify with the React DevTools Profiler and the "why did this render" highlight.` },
  { id: "re32", c: "React", d: "Medium", q: `Explain the component lifecycle in hooks terms.`, a: `Mount = first render then useEffect with an empty dep array. Update = re-render then effects whose deps changed. Unmount = the cleanup functions run. There is no direct componentDidUpdate; you compare with a ref if you truly need the previous value. getDerivedStateFromProps maps to computing during render or keying the component to reset it.` },
  { id: "re33", c: "React", d: "Hard", q: `How would you build a design-system component that is accessible and flexible?`, a: `Start from semantics and roles, support keyboard interaction per the WAI-ARIA authoring practices, forward refs and spread the remaining props to the root, allow an asChild/polymorphic escape hatch, keep styling injectable through className or tokens rather than hard-coded, and control/uncontrol the value with the standard value/defaultValue/onChange trio. Headless primitives like Radix exist because this is genuinely hard.` },
  { id: "re34", c: "React", d: "Medium", q: `What is the difference between state colocation and global state?`, a: `Colocation keeps state next to the component that uses it, which limits re-render scope, keeps code deletable, and avoids stale global data. Promote to global only when several distant components need the same value, or when it must survive route changes. Global-by-default is one of the most common structural mistakes in React codebases.` },
  { id: "re35", c: "React", d: "Medium", q: `How do you handle routing and route protection in a React SPA?`, a: `React Router v6+ with nested routes, loaders and layout routes, or the file-based router of Next.js. Protection: a guard component or a loader that checks the session and redirects, plus server-side enforcement — client route guards are UX, never security. Preserve the intended URL to redirect back after login.` },
  { id: "re36", c: "React", d: "Hard", q: `How do you debug a slow React page end to end?`, a: `Reproduce with production build. Use the Profiler to find which components render and why; use the Performance tab for long tasks, layout thrash and script cost; check the Network waterfall for blocking requests and bundle size; check for large lists, unmemoised context, and expensive derived work during render. Fix the biggest contributor first, measure again, and record the numbers.`, t: `Have a concrete story ready: what was slow, what you measured, what changed, by how much.` },
  { id: "re37", c: "React", d: "Medium", q: `What is the children prop and why is composition powerful for performance?`, a: `children is a prop like any other, but elements passed as children are created by the parent's parent, so they keep the same reference when the middle component re-renders. Wrapping expensive subtrees as children of a stateful component means state changes in that component do not re-render the passed subtree.` },
  { id: "re38", c: "React", d: "Medium", q: `How do you handle forms with complex validation?`, a: `React Hook Form with a Zod resolver: uncontrolled fields for performance, schema as single source of truth shared with the backend types, field-level and cross-field validation, dependent/conditional fields via watch, and array fields via useFieldArray. Always re-validate on the server — client validation is UX only.`, t: `If you have built a dynamic JSON-schema-driven form, describe it here — it is a strong differentiator.` },
  { id: "re39", c: "React", d: "Hard", q: `What is tearing and how does React prevent it?`, a: `Tearing is when different parts of one render read different values of the same external store because rendering was interrupted and the store changed mid-render. React solves it for its own state via the fiber snapshot, and for external stores via useSyncExternalStore, which forces a synchronous re-read and re-render if the snapshot changed.` },
  { id: "re40", c: "React", d: "Medium", q: `How do you internationalise and format data in a React app?`, a: `Use Intl.NumberFormat, Intl.DateTimeFormat and Intl.RelativeTimeFormat rather than hand-rolled formatting, keep the locale in context, and load message bundles lazily per locale. Beware SSR mismatches from server/client timezone differences — format on the client or pin a timezone explicitly.` },
  { id: "re41", c: "React", d: "Medium", q: `What is the difference between React.memo and useMemo for a component?`, a: `React.memo wraps a component and compares props shallowly to skip rendering it. useMemo caches a value inside a component. Memoising the element itself (const el = useMemo(() => <Heavy/>, [])) also works and does not require the child to be wrapped. Both fail if the props are recreated each render.` },
  { id: "re42", c: "React", d: "Hard", q: `How would you implement infinite scroll correctly?`, a: `Use IntersectionObserver on a sentinel element rather than scroll listeners, fetch with cursor-based pagination (not offset, which duplicates rows when data shifts), append into a cache like useInfiniteQuery, guard against duplicate in-flight requests, restore scroll position on back navigation, and pair it with virtualisation once the list grows large.` },
  { id: "re43", c: "React", d: "Medium", q: `How do you share state between tabs or windows?`, a: `BroadcastChannel for same-origin messaging, the storage event on localStorage as a fallback, or a service worker as a coordinator. Typical use: logging out everywhere when one tab logs out, and syncing a cache. Guard against echo loops by tagging messages with a source id.` },
  { id: "re44", c: "React", d: "Medium", q: `What is a portal and when do you need one?`, a: `createPortal renders children into a different DOM node while keeping them in the React tree, so context and event bubbling through React still work. Needed for modals, tooltips and dropdowns that would otherwise be clipped by overflow:hidden or trapped in a stacking context. Remember focus trapping and restoring focus on close.` },
  { id: "re45", c: "React", d: "Hard", q: `Walk through what happens from setState to pixels on screen.`, a: `setState schedules an update with a lane priority on the fiber. React begins the render phase, calls the component, diffs the returned tree, marks effects, and can pause for higher-priority work. The commit phase applies mutations, runs layout effects synchronously, and lets the browser paint. Passive effects run after paint. Then style, layout, paint and composite happen in the browser.` },

  // =============================== NODE.JS =================================
  { id: "no1", c: "Node.js", d: "Easy", q: `What is Node.js and how does it handle concurrency with a single thread?`, a: `Node runs JS on V8 with libuv providing an event loop and a thread pool. The JS thread is single, but I/O is delegated to the OS (epoll/kqueue) or to the libuv thread pool, and callbacks are queued back. So Node handles many concurrent connections cheaply, but any CPU-heavy synchronous work blocks everything.` },
  { id: "no2", c: "Node.js", d: "Medium", q: `What are the phases of the libuv event loop?`, a: `timers (expired setTimeout/setInterval), pending callbacks, idle/prepare (internal), poll (retrieve I/O events and execute their callbacks, may block), check (setImmediate), close callbacks. Between each phase Node drains nextTick and microtask queues.` },
  { id: "no3", c: "Node.js", d: "Medium", q: `How do you handle CPU-intensive work in Node?`, a: `Offload it: worker_threads for in-process parallelism with shared memory via SharedArrayBuffer, child_process/fork for isolation, or a separate queue worker (BullMQ, SQS) for anything long-running. Cluster mode or multiple containers scale across cores. Chunking with setImmediate helps only for medium tasks.` },
  { id: "no4", c: "Node.js", d: "Medium", q: `Explain streams and why they matter.`, a: `Streams process data in chunks instead of buffering everything in memory: Readable, Writable, Duplex, Transform. pipeline() wires them with correct error propagation and cleanup (pipe() leaks on error). They are how you serve large files, parse big CSVs, and proxy uploads without your RSS ballooning.` },
  { id: "no5", c: "Node.js", d: "Medium", q: `What is backpressure and how do streams handle it?`, a: `Backpressure is the consumer being slower than the producer. write() returns false when the internal buffer exceeds highWaterMark; the producer should pause until the drain event. pipe/pipeline handle this automatically. Ignoring it turns into unbounded memory growth and OOM kills in containers.` },
  { id: "no6", c: "Node.js", d: "Medium", q: `Difference between cluster, worker_threads and child_process.`, a: `cluster forks processes sharing a listening socket to use all cores for a server. worker_threads are threads in one process, cheaper to start, able to share memory — good for CPU work. child_process spawns arbitrary processes (including non-Node binaries) with IPC. In containers, one process per container plus horizontal scaling often beats cluster.` },
  { id: "no7", c: "Node.js", d: "Medium", q: `How do you handle uncaught exceptions and unhandled rejections?`, a: `Log with full context, then exit and let the supervisor (PM2, systemd, Kubernetes) restart — the process state after an uncaught exception is untrusted. Never use uncaughtException to keep serving traffic. Do graceful shutdown: stop accepting connections, finish in-flight requests with a timeout, close DB pools, then exit.` },
  { id: "no8", c: "Node.js", d: "Medium", q: `What does graceful shutdown look like in production?`, a: `On SIGTERM: flip a readiness flag so the load balancer stops sending traffic, call server.close() to stop new connections, wait for in-flight requests up to a deadline, drain the job queue consumer, close DB/Redis pools, then process.exit(0). Force-exit on a timer so a stuck socket cannot hang the deploy.` },
  { id: "no9", c: "Node.js", d: "Medium", q: `How do you manage configuration and secrets in a Node service?`, a: `Environment variables injected by the platform, validated at boot with a schema so the process fails fast on a missing var. Secrets come from a manager (AWS Secrets Manager, Vault, Kubernetes secrets), never from committed .env files. Keep separate config per environment, and never ship server secrets into a client bundle.` },
  { id: "no10", c: "Node.js", d: "Medium", q: `How does require caching work and why does it matter?`, a: `require caches modules by resolved path in require.cache, so a module body executes once per process and the exports object is shared. That makes modules effective singletons — good for a DB pool, dangerous for mutable module-level state in a multi-tenant handler. ESM has a similar module registry.` },
  { id: "no11", c: "Node.js", d: "Medium", q: `What is the difference between Buffer and string handling?`, a: `Buffer is a fixed-length raw byte array outside the V8 heap. Strings are UTF-16 in the heap. Converting between them costs a copy and can corrupt multibyte characters if you slice a buffer mid-character — use string_decoder for streamed text. For binary work (crypto, files, images), stay in buffers.` },
  { id: "no12", c: "Node.js", d: "Hard", q: `How do you profile and fix a Node memory leak?`, a: `Watch RSS and heapUsed over time. Take heap snapshots with --inspect and compare retained sizes, or use clinic.js/heapdump. Typical culprits: unbounded in-memory caches or Maps, listeners added per request, closures held by timers, global arrays of logs, and streams never destroyed. Fix with bounded LRU caches, removeListener, and pipeline cleanup.` },
  { id: "no13", c: "Node.js", d: "Medium", q: `How do you do logging properly in a Node service?`, a: `Structured JSON logs (pino, winston) to stdout, with levels, a request id from a correlation header, and no PII or secrets. Let the platform ship them to the aggregator. Add trace ids via AsyncLocalStorage so every log inside one request carries the same id without threading a parameter everywhere.` },
  { id: "no14", c: "Node.js", d: "Hard", q: `What is AsyncLocalStorage and what problem does it solve?`, a: `It provides per-async-context storage, the Node equivalent of thread-local state. Run the request handler inside als.run(store, fn) and any async code beneath can read the store — request id, user, tenant — without passing it through every function signature. It is what modern tracing and context libraries are built on.` },
  { id: "no15", c: "Node.js", d: "Medium", q: `How do you implement retries and timeouts for outbound calls?`, a: `Always set a connect and a read timeout — no timeout means a hung dependency exhausts your sockets. Retry only idempotent operations, with exponential backoff plus jitter and a max attempt count, and use an idempotency key for POSTs that must not double-execute. Add a circuit breaker so a failing dependency fails fast instead of queuing.` },
  { id: "no16", c: "Node.js", d: "Medium", q: `What are the main npm dependency concerns in production?`, a: `Lockfile committed and npm ci in CI for reproducible installs; audit and Dependabot/Renovate for CVEs; caret ranges plus no lockfile is how a build breaks overnight; devDependencies excluded from the production image; watch for postinstall scripts, typosquatting and unmaintained transitive packages. Prune with npm ls and keep the dependency count deliberate.` },
  { id: "no17", c: "Node.js", d: "Medium", q: `How would you schedule background jobs?`, a: `For anything important, a real queue: BullMQ on Redis, or SQS/Cloud Tasks. Requirements: at-least-once delivery, idempotent handlers, retries with backoff, a dead-letter queue, visibility into failures, and concurrency limits. node-cron inside the web process breaks the moment you run two replicas — you get duplicate runs unless you add a distributed lock.`, t: `The "we scaled to 2 pods and the cron ran twice" story is a favourite interview scenario.` },
  { id: "no18", c: "Node.js", d: "Medium", q: `How do you handle file uploads safely?`, a: `Stream to storage rather than buffering; cap size with limits; validate content type by sniffing magic bytes, not the client-provided header or extension; generate your own filename; store outside the web root or in object storage; scan if untrusted. Best pattern at scale: presigned S3 URLs so the file never transits your server.` },
  { id: "no19", c: "Node.js", d: "Hard", q: `What happens when Node runs out of heap and how do you tune it?`, a: `V8 has a heap cap (historically ~1.5-4GB depending on version/arch); exceeding it aborts with a fatal OOM. Tune with --max-old-space-size, but treat it as a symptom: usually the fix is streaming instead of buffering, bounded caches, or pagination. In containers, set the flag below the container memory limit or the kernel OOM killer gets there first.` },
  { id: "no20", c: "Node.js", d: "Medium", q: `Explain the difference between blocking and non-blocking APIs with examples.`, a: `fs.readFileSync blocks the loop for the duration of the read; fs.promises.readFile does not. Also blocking: JSON.parse on a huge payload, crypto.pbkdf2Sync, large regex backtracking, and synchronous compression. In a server, one blocking call stalls every concurrent request, which shows up as p99 latency spikes rather than errors.` },
  { id: "no21", c: "Node.js", d: "Medium", q: `How do you hash passwords in Node?`, a: `bcrypt, scrypt or argon2 with a per-user salt and a cost factor tuned so hashing takes tens of milliseconds. Never MD5/SHA on their own — they are fast, which is exactly wrong here. Use the async variants so the thread pool handles it, compare with a constant-time function, and re-hash on login when you raise the cost factor.` },
  { id: "no22", c: "Node.js", d: "Medium", q: `What is the difference between the crypto module's randomBytes and Math.random?`, a: `Math.random is a fast, non-cryptographic PRNG and is predictable — never use it for tokens, OTPs, session ids or password resets. crypto.randomBytes and crypto.randomUUID draw from the OS CSPRNG. randomBytes has a sync and async form; the async form uses the thread pool.` },
  { id: "no23", c: "Node.js", d: "Hard", q: `How do you keep a Node service warm and fast under load?`, a: `Keep connection pools (DB, Redis, HTTP agents with keepAlive) alive and sized to the DB limits, cache hot reads, avoid per-request module work, precompute what you can at boot, set an appropriate UV_THREADPOOL_SIZE if you do heavy fs/crypto, and load-test to find the knee. Watch event loop lag as a first-class metric — it is the earliest signal of saturation.` },
  { id: "no24", c: "Node.js", d: "Medium", q: `What is event loop lag and how do you measure it?`, a: `The delay between when a timer should fire and when it does, which reflects how long the loop is blocked. Measure with perf_hooks monitorEventLoopDelay or a simple setInterval drift check, and export it to Prometheus. Sustained lag above a few tens of milliseconds means something synchronous is hogging the thread.` },
  { id: "no25", c: "Node.js", d: "Medium", q: `How would you implement rate limiting in Node?`, a: `Token bucket or sliding window counters in Redis so the limit is shared across replicas (in-memory limiting breaks when you scale out). Key by user id for authenticated traffic and by IP plus route for anonymous. Return 429 with Retry-After. Push coarse limits to the edge (Nginx, Cloudflare, API gateway) and keep fine-grained business limits in the app.` },
  { id: "no26", c: "Node.js", d: "Medium", q: `How do you handle timezones and dates in a Node backend?`, a: `Store timestamps in UTC, transmit ISO-8601 with offset, and convert at the presentation layer using the user's timezone. Use date-fns-tz, Luxon or the Temporal API rather than manual offset maths, and pin the container TZ so behaviour is identical across environments. Date-only values (birth dates, due dates) should not be timestamps at all.` },
  { id: "no27", c: "Node.js", d: "Hard", q: `What is the difference between Node's HTTP keep-alive defaults and what should you set?`, a: `Node's default global agent historically had keep-alive disabled, causing a new TCP handshake per outbound request. Set an agent with keepAlive: true and a maxSockets cap. On the server side, tune keepAliveTimeout above your load balancer's idle timeout, otherwise you get sporadic 502s when the LB reuses a socket Node has just closed.`, t: `This exact 502 race is a classic production war story — worth remembering.` },
  { id: "no28", c: "Node.js", d: "Medium", q: `How do you structure a Node/Express codebase for a growing team?`, a: `Layer by responsibility: routes -> controllers (HTTP only) -> services (business logic, framework-free) -> repositories (data access). Group by feature module rather than by technical type once the app grows. Keep validation at the edge, keep DB models out of controllers, centralise error handling, and make the service layer unit-testable without an HTTP server.` },

  // ======================= EXPRESS & API DESIGN ============================
  { id: "ex1", c: "Express & APIs", d: "Easy", q: `What is middleware in Express and how does the chain work?`, a: `A function with (req, res, next) that runs in registration order for matching paths. It can mutate req/res, end the response, or call next() to continue — or next(err) to jump to error middleware. Forgetting to call next or send a response leaves the request hanging until timeout.` },
  { id: "ex2", c: "Express & APIs", d: "Medium", q: `How do you write error-handling middleware, and what changes with async handlers?`, a: `Error middleware has four parameters (err, req, res, next) and must be registered last. Express 4 does not catch rejected promises from async handlers, so wrap them (express-async-errors or a catchAsync helper) or the request hangs. Express 5 forwards async rejections automatically. Map known error types to status codes centrally and never leak stack traces in production.` },
  { id: "ex3", c: "Express & APIs", d: "Medium", q: `Design a REST API for a resource — what are the conventions?`, a: `Plural nouns for collections, HTTP verbs for actions, no verbs in paths. GET /loans, GET /loans/:id, POST /loans, PATCH /loans/:id, DELETE /loans/:id. Nest one level for real containment (/loans/:id/documents). Status codes: 200/201/204, 400 validation, 401 unauthenticated, 403 unauthorised, 404, 409 conflict, 422, 429, 5xx. Support filtering, sorting and pagination via query params, and version the API.` },
  { id: "ex4", c: "Express & APIs", d: "Medium", q: `PUT vs PATCH vs POST — including idempotency.`, a: `POST creates or triggers, is not idempotent. PUT replaces the whole resource and is idempotent — sending it twice yields the same state. PATCH applies a partial update and is idempotent only if written that way (a "increment balance" patch is not). Idempotency matters because clients and gateways retry.` },
  { id: "ex5", c: "Express & APIs", d: "Medium", q: `How do you paginate an API and what are the trade-offs?`, a: `Offset/limit is simple and allows jumping to a page, but is slow on deep offsets and skips or duplicates rows when data changes underneath. Cursor/keyset pagination uses a stable sort key (created_at + id) and is O(1) for any depth and stable under inserts, but cannot jump to page N. For infinite feeds use cursors; for admin tables with page numbers, offset with a capped depth.` },
  { id: "ex6", c: "Express & APIs", d: "Medium", q: `How do you validate request input?`, a: `Validate at the boundary with a schema (Zod, Joi, celebrate) covering body, params, query and headers; strip unknown keys so mass assignment cannot set role or is_admin; coerce types explicitly; return a machine-readable error listing field paths. Reuse the same schema to derive TypeScript types so the contract stays in one place.` },
  { id: "ex7", c: "Express & APIs", d: "Medium", q: `Explain CORS end to end.`, a: `The browser enforces the same-origin policy. Simple requests get an Origin header and the server must answer with Access-Control-Allow-Origin. Non-simple requests (custom headers, PUT/DELETE, JSON content type in some cases) trigger an OPTIONS preflight, answered with allowed methods, headers and Max-Age. Cookies require credentials: "include" plus Allow-Credentials: true and an explicit origin — the wildcard is rejected. CORS is a browser rule, not server security.`, t: `Very common: "I set Allow-Origin * and cookies still fail" — explain why.` },
  { id: "ex8", c: "Express & APIs", d: "Medium", q: `REST vs GraphQL vs gRPC — when would you pick each?`, a: `REST: simple, cacheable at HTTP level, great default for CRUD and public APIs. GraphQL: many clients with different data needs, deep nesting, avoiding over/under-fetching — at the cost of caching complexity, N+1 risk (solve with DataLoader) and query-depth abuse. gRPC: internal service-to-service, strict contracts, streaming, low latency, but poor browser support without a proxy.` },
  { id: "ex9", c: "Express & APIs", d: "Medium", q: `How do you version an API without breaking clients?`, a: `URI versioning (/v1/) is explicit and cache-friendly; header/media-type versioning is cleaner but harder to debug. Prefer additive, backwards-compatible changes: new optional fields, never repurpose an existing one. When you must break, run both versions, publish a deprecation timeline with Sunset headers, and measure who is still calling the old one before removing it.` },
  { id: "ex10", c: "Express & APIs", d: "Hard", q: `What are idempotency keys and how do you implement them?`, a: `The client sends a unique key per logical operation. The server stores key -> response with a status, inside the same transaction or with a unique index. A repeat with the same key returns the stored response instead of executing again; a concurrent duplicate gets 409 or waits. Essential for payments and anything that creates money movement, since networks retry.` },
  { id: "ex11", c: "Express & APIs", d: "Medium", q: `How do you design consistent error responses?`, a: `One envelope with a stable machine-readable code, a human message, a field-level details array, and a request/trace id. Do not put error text in a 200 response. Map internal exceptions to codes in one place. Log the full error server-side with the same trace id so support can correlate what the user saw with the log line.` },
  { id: "ex12", c: "Express & APIs", d: "Medium", q: `How do you handle long-running operations in an HTTP API?`, a: `Do not hold the request open. Accept the work, return 202 with a job id and a status URL, process asynchronously via a queue, and let the client poll or receive a webhook/websocket event. Store job status, make the worker idempotent, and expose progress and failure reasons.` },
  { id: "ex13", c: "Express & APIs", d: "Medium", q: `How do webhooks work and how do you make them reliable?`, a: `You POST to a subscriber URL on an event. Reliability: sign the payload with an HMAC and a timestamp so receivers can verify and reject replays, retry with exponential backoff on non-2xx, deliver at-least-once so receivers must be idempotent, include an event id and type, and expose a delivery log with manual replay. Receivers should return 2xx fast and process asynchronously.` },
  { id: "ex14", c: "Express & APIs", d: "Medium", q: `Compare polling, long polling, SSE and WebSockets.`, a: `Polling is simple and wasteful. Long polling holds the request until data arrives. SSE is a one-way server-to-client stream over plain HTTP with automatic reconnect and event ids — ideal for notifications and progress. WebSockets are full-duplex and best for chat, collaboration and trading, but need sticky sessions or a pub/sub backplane (Redis) when you run multiple instances.` },
  { id: "ex15", c: "Express & APIs", d: "Medium", q: `What HTTP caching headers matter for an API and a SPA?`, a: `Cache-Control (max-age, s-maxage, no-store, stale-while-revalidate), ETag/If-None-Match for conditional GETs returning 304, Last-Modified as a weaker alternative, and Vary so caches key on Accept/Authorization. For a SPA: hashed asset filenames with immutable long max-age, and index.html with no-cache so users get the new build.` },
  { id: "ex16", c: "Express & APIs", d: "Medium", q: `How do you secure an Express app in practice?`, a: `helmet for security headers, strict CORS allowlist, rate limiting, input validation, parameterised queries, cookies with httpOnly/secure/sameSite, a body size limit, disable x-powered-by, keep dependencies patched, enforce HTTPS/HSTS behind the proxy, and set trust proxy correctly so IP-based logic and secure cookies work behind a load balancer.` },
  { id: "ex17", c: "Express & APIs", d: "Hard", q: `What is the N+1 problem in an API layer and how do you fix it?`, a: `Fetching a list then querying per item — 1 + N round trips. Fix with a single join or an aggregation, a batched IN query keyed by id, DataLoader in GraphQL for per-request batching and dedupe, or Mongoose populate with lean and selected fields. Detect it by logging query counts per request in development.` },
  { id: "ex18", c: "Express & APIs", d: "Medium", q: `How do you document an API and keep the docs true?`, a: `OpenAPI as the contract, generated from code or from the same schemas used for validation so drift is impossible. Serve Swagger UI, generate typed clients for the frontend, and add contract tests in CI. Hand-written docs in a wiki are stale within a sprint.` },
  { id: "ex19", c: "Express & APIs", d: "Medium", q: `How would you implement multi-tenancy in an API?`, a: `Resolve the tenant from the token or subdomain into request context (AsyncLocalStorage), and enforce it in the data layer — a base repository that always adds the tenant filter, so a forgotten where clause cannot leak data. Options: shared schema with a tenant column, schema-per-tenant, or database-per-tenant, trading isolation against operational cost.` },
  { id: "ex20", c: "Express & APIs", d: "Medium", q: `What is the difference between authentication and authorisation, and where do you enforce them?`, a: `Authentication proves who the caller is; authorisation decides what they may do. Authenticate once in middleware; authorise per resource, ideally in the service layer where you know the object's owner — route-level checks miss "user A editing user B's loan". Model with RBAC for coarse roles and ABAC/policies for row-level rules.` },
  { id: "ex21", c: "Express & APIs", d: "Medium", q: `How do you handle file downloads and large responses?`, a: `Stream from storage rather than reading into memory, set Content-Type, Content-Disposition and Content-Length, support Range requests for resumable/media downloads, and prefer presigned URLs so the object store serves the bytes. Compress text responses, but never gzip already-compressed formats.` },
  { id: "ex22", c: "Express & APIs", d: "Hard", q: `How do you keep an API backward compatible with a mobile app you cannot force-update?`, a: `Treat the contract as permanent: additive changes only, tolerant readers, feature flags keyed by app version, and a minimum-supported-version endpoint that can trigger a soft or hard update prompt. Keep server-driven configuration so behaviour can change without a release, and log the version distribution so you know when it is safe to drop support.`, t: `Directly relevant if you have shipped an Android app to internal users — use that example.` },
  { id: "ex23", c: "Express & APIs", d: "Medium", q: `What is a BFF (backend for frontend) and why use one?`, a: `A thin API tailored to one client that aggregates and reshapes calls to downstream services, keeping the client simple and reducing round trips over mobile networks. It also holds client-specific concerns (auth token exchange, response trimming) out of core services. Cost: another deployable and a risk of it becoming a second business-logic layer.` },
  { id: "ex24", c: "Express & APIs", d: "Medium", q: `How do you test an API?`, a: `Unit-test services with the DB mocked, integration-test routes with supertest against a real database in a container (testcontainers or a dedicated test DB) with per-test transactions or truncation, and contract-test against the OpenAPI schema. Cover auth failures, validation errors and edge pagination — not just the happy path.` },
  { id: "ex25", c: "Express & APIs", d: "Medium", q: `What does "trust proxy" do and why does it bite people?`, a: `Behind a load balancer, req.ip is the proxy's IP and req.protocol is http, so secure cookies never set and rate limiting buckets every user together. Setting app.set("trust proxy", ...) makes Express read X-Forwarded-For and X-Forwarded-Proto. Trust only your known proxy hops — blindly trusting the header lets clients spoof their IP.` },
  { id: "ex26", c: "Express & APIs", d: "Hard", q: `How would you design a bulk import endpoint for 100k rows?`, a: `Accept a file upload to object storage and return a job id rather than parsing inline. A worker streams and parses in batches, validates per row, writes with bulk operations, and records per-row outcomes. Provide progress, a downloadable error report, idempotency by file hash, partial-success semantics, and back-pressure so one import cannot starve the queue.` },

  // ========================= MONGODB & MONGOOSE ============================
  { id: "mo1", c: "MongoDB", d: "Easy", q: `What is MongoDB and when is a document database the right choice?`, a: `A document store keeping BSON documents in collections with a flexible schema. Good fit when data is naturally hierarchical and read together (a loan with its documents and status history), when the shape varies per record, or when you need horizontal sharding. Weak fit for heavy multi-entity joins, strong relational integrity and complex reporting — that is still SQL's home turf.`, t: `Answering "it depends" with concrete criteria beats "Mongo is faster".` },
  { id: "mo2", c: "MongoDB", d: "Medium", q: `Embedding vs referencing — how do you decide?`, a: `Embed when the child is owned by the parent, read together, bounded in size, and updated together (addresses, line items). Reference when the child is large, unbounded, shared across parents, or independently queried and updated. Watch the 16MB document limit and the massive-array anti-pattern; unbounded arrays are the most common Mongo modelling mistake.` },
  { id: "mo3", c: "MongoDB", d: "Medium", q: `How do indexes work in MongoDB and what types exist?`, a: `B-tree indexes on one or more fields. Types: single field, compound, multikey (arrays), text, geospatial, hashed, wildcard, TTL, partial and sparse. An index speeds reads but costs writes and RAM. Verify usage with explain("executionStats") and look for IXSCAN rather than COLLSCAN, and for keysExamined close to nReturned.` },
  { id: "mo4", c: "MongoDB", d: "Hard", q: `Explain the ESR rule for compound indexes.`, a: `Order compound index keys as Equality, Sort, Range. Equality-matched fields first narrow the scan; the sort field next lets Mongo return sorted results without an in-memory sort (which fails above 100MB without allowDiskUse); range fields last because they widen the scan. Getting the order wrong is why an index exists but is not used efficiently.` },
  { id: "mo5", c: "MongoDB", d: "Medium", q: `What does the aggregation pipeline give you? Name key stages.`, a: `A staged data-processing pipeline: $match (filter early, before $project/$group, so indexes apply), $group, $project/$addFields, $sort, $limit/$skip, $lookup (left outer join), $unwind, $facet for multiple outputs in one pass, $bucket, $out/$merge to write results. Order matters enormously for performance.` },
  { id: "mo6", c: "MongoDB", d: "Medium", q: `How does $lookup work and what are its limits?`, a: `It performs a left outer join into an array field on the same database. It is slower than a relational join, cannot use an index on the foreign collection in all forms, does not work across shards for some variants, and can explode document size when the joined side is large. Frequent $lookup usually signals that the data model should embed or duplicate a few fields instead.` },
  { id: "mo7", c: "MongoDB", d: "Medium", q: `Do transactions exist in MongoDB, and when do you need them?`, a: `Yes — multi-document ACID transactions on replica sets (4.0+) and sharded clusters (4.2+), started from a session. Single-document writes are already atomic, so a good document model removes the need for most transactions. Use them for cross-collection invariants like debiting one account and crediting another. Costs: they hold locks, have a default 60s limit, and need retry logic for TransientTransactionError.` },
  { id: "mo8", c: "MongoDB", d: "Hard", q: `Explain replica sets, elections and read/write concerns.`, a: `A replica set has one primary and several secondaries replicating via the oplog. If the primary is unreachable, a majority of members elect a new one. writeConcern controls durability (w:1 vs w:"majority" plus journal), readConcern controls visibility ("local", "majority", "linearizable"), and readPreference routes reads to primary or secondaries — secondaries can serve stale data. For financial data, use w:majority.` },
  { id: "mo9", c: "MongoDB", d: "Hard", q: `What is sharding and how do you choose a shard key?`, a: `Sharding partitions a collection across shards by a shard key, routed by mongos with config servers holding metadata. A good key has high cardinality, even write distribution, and is present in most queries so they can be targeted rather than scattered. Monotonic keys like ObjectId or timestamps create a hot shard; hashed or compound keys spread writes. Changing a shard key later is painful — decide carefully.` },
  { id: "mo10", c: "MongoDB", d: "Medium", q: `What is the difference between updateOne, findOneAndUpdate, and bulkWrite?`, a: `updateOne applies the update and returns counts. findOneAndUpdate atomically returns the document (before or after, via returnDocument) — useful for counters and claim-a-job patterns. bulkWrite batches many operations in one round trip with ordered or unordered execution; unordered continues past failures and is faster.` },
  { id: "mo11", c: "MongoDB", d: "Medium", q: `Explain Mongoose schemas, models and middleware.`, a: `A Schema defines shape, types, validators, defaults, virtuals and indexes; a Model is the queryable wrapper over a collection. Middleware (pre/post hooks) runs on save, validate, remove and query operations — used for hashing passwords, timestamps and audit trails. Careful: document middleware does not run on updateOne/findOneAndUpdate unless you write query middleware too.`, t: `The "my pre-save hash did not run on findOneAndUpdate" bug is a great real answer.` },
  { id: "mo12", c: "MongoDB", d: "Medium", q: `What does .lean() do in Mongoose and when should you use it?`, a: `It returns plain JS objects instead of hydrated Mongoose documents, skipping getters, virtuals, defaults and change tracking. Substantially faster and lighter for read-only queries such as list endpoints. Do not use it when you need to call .save() or rely on virtuals.` },
  { id: "mo13", c: "MongoDB", d: "Medium", q: `How does populate work and what is its cost?`, a: `populate issues a separate query for the referenced ids and stitches results in the application, so it is effectively a client-side join — nested populate multiplies round trips. Always select only the fields you need, combine with lean, and consider denormalising a few frequently displayed fields (name, status) onto the parent to avoid the population entirely.` },
  { id: "mo14", c: "MongoDB", d: "Medium", q: `How do you model a one-to-many relationship with unbounded growth?`, a: `Reference from the child to the parent and index that field, rather than pushing into an array on the parent. Arrays that grow forever break the 16MB limit, force document rewrites and moves, and make indexes multikey and huge. If you need recent items on the parent, keep a bounded subset (the outlier/bucket pattern) alongside the referenced collection.` },
  { id: "mo15", c: "MongoDB", d: "Medium", q: `What are TTL indexes and where are they useful?`, a: `An index on a date field with expireAfterSeconds; a background task deletes expired documents roughly every 60 seconds. Perfect for sessions, OTPs, cached computations and log-style data. Not exact-time deletion, and it will not fire if the field is missing or not a date.` },
  { id: "mo16", c: "MongoDB", d: "Hard", q: `How do you diagnose a slow MongoDB query?`, a: `Enable the profiler or slow-query log, then run explain("executionStats"): check stage (COLLSCAN vs IXSCAN), totalKeysExamined and totalDocsExamined versus nReturned, whether SORT appeared in memory, and the winning plan. Fix with the right compound index (ESR), projecting fewer fields, moving $match earlier, or covering the query entirely with an index.` },
  { id: "mo17", c: "MongoDB", d: "Medium", q: `What is a covered query?`, a: `A query answered entirely from an index without touching documents — all queried and returned fields are in the index and _id is excluded from the projection unless indexed. explain shows totalDocsExamined: 0. It is the cheapest read you can get and worth designing for on hot list endpoints.` },
  { id: "mo18", c: "MongoDB", d: "Medium", q: `How do you handle schema migrations in MongoDB?`, a: `Because the schema is flexible you can migrate lazily: write new fields, read with a fallback, and backfill in batches with a script that is resumable and rate-limited. Version documents with a schemaVersion field. For breaking changes, deploy tolerant readers first, backfill, then remove old code — the same expand/contract pattern as SQL.` },
  { id: "mo19", c: "MongoDB", d: "Hard", q: `What are change streams and what would you use them for?`, a: `A resumable stream of oplog events on a collection, database or cluster, available on replica sets. Use for cache invalidation, search index sync, audit trails, and event-driven workflows without dual writes. Store the resume token to survive restarts, and remember the oplog window limits how far back you can resume.` },
  { id: "mo20", c: "MongoDB", d: "Medium", q: `How do you prevent NoSQL injection?`, a: `Never pass raw request objects into a query — a body of { "password": { "$gt": "" } } turns into an always-true condition. Cast and validate types with a schema, sanitise operators (express-mongo-sanitize), and avoid $where and mapReduce with user input entirely. Mongoose casting helps but does not replace validation.` },
  { id: "mo21", c: "MongoDB", d: "Medium", q: `What is the difference between find and aggregate for reporting?`, a: `find is for retrieving documents with simple filters and projections. aggregate can group, join, reshape, bucket, and compute — everything reporting needs — but expensive pipelines compete with production traffic. For heavy analytics, run on a secondary with a dedicated read preference, precompute with $merge into a summary collection, or export to a warehouse.` },
  { id: "mo22", c: "MongoDB", d: "Medium", q: `How do you implement optimistic concurrency in MongoDB?`, a: `Keep a version field and include it in the filter: updateOne({ _id, version: 7 }, { $set: {...}, $inc: { version: 1 } }). If matchedCount is 0, someone else wrote first — return 409 and let the client re-read and retry. Mongoose does this with the __v field when versionKey and optimisticConcurrency are enabled.` },
  { id: "mo23", c: "MongoDB", d: "Medium", q: `What are the connection pooling considerations for Mongo in Node?`, a: `The driver keeps a pool per process (default maxPoolSize 100). Create the client once and reuse it — connecting per request destroys performance. Size the pool against the server's connection limit multiplied by your replica count, especially in serverless where each cold start opens a new pool. Set serverSelectionTimeoutMS and socket timeouts so failures surface fast.` },
  { id: "mo24", c: "MongoDB", d: "Hard", q: `Explain the WiredTiger storage engine essentials.`, a: `Document-level concurrency control with MVCC, compression (snappy by default) for data and prefix compression for indexes, and a cache sized around 50% of RAM by default. Checkpoints every 60 seconds plus a journal for durability between them. Working set fitting in cache is the single biggest performance factor.` },
  { id: "mo25", c: "MongoDB", d: "Medium", q: `How would you do full-text search in MongoDB, and when do you outgrow it?`, a: `A text index supports stemming and scoring for basic search; Atlas Search adds Lucene-backed relevance, fuzzy matching, facets and autocomplete. You outgrow it when you need typo tolerance across many fields, synonyms, complex ranking or high query volume — then a dedicated engine (Elasticsearch, OpenSearch, Typesense) fed via change streams is the right call.` },
  { id: "mo26", c: "MongoDB", d: "Medium", q: `What is the aggregation $facet stage good for?`, a: `Running several sub-pipelines over the same input in one pass — classically returning a page of results and the total count together, or a list plus filter counts for a search UI. It avoids two round trips, but each facet processes the same input, so filter with $match before the facet.` },
  { id: "mo27", c: "MongoDB", d: "Medium", q: `How do you back up and restore MongoDB safely?`, a: `Managed snapshots (Atlas continuous backup with point-in-time restore) or filesystem snapshots of a consistent volume; mongodump/mongorestore is fine for small datasets but slow and not point-in-time. What matters in an interview: you test restores regularly, you know your RPO/RTO, and backups are encrypted and stored off the primary account.` },
  { id: "mo28", c: "MongoDB", d: "Medium", q: `When would you choose PostgreSQL over MongoDB for a new service?`, a: `When the data is relational with real integrity constraints, when you need multi-table transactions as the norm, complex ad-hoc joins and reporting, strict schemas for compliance, or window functions. Postgres also handles JSONB well, so "we need flexible fields" alone is not a reason to leave SQL. Fintech ledgers almost always live in a relational store.`, t: `Showing you can argue against your own stack reads as senior.` },
  { id: "mo29", c: "MongoDB", d: "Hard", q: `How do you keep counts and aggregates fast on a large collection?`, a: `countDocuments scans; estimatedDocumentCount reads metadata but ignores filters. For filtered counts, keep a covering index, cap counting depth ("1000+ results"), or maintain rollup counters updated with $inc in the same write path or via change streams. Precompute daily aggregates into a summary collection with $merge.` },
  { id: "mo30", c: "MongoDB", d: "Medium", q: `What is the outlier pattern and other Mongo schema patterns worth naming?`, a: `Outlier: handle the rare huge document with an overflow collection. Bucket: group time-series points into per-hour documents. Computed: store precomputed aggregates. Subset: keep the hot slice embedded and the rest referenced. Extended reference: duplicate a few fields to avoid joins. Attribute: index sparse key/value arrays. Naming these signals real modelling experience.` },
  { id: "mo31", c: "MongoDB", d: "Medium", q: `How do you enforce data integrity without foreign keys?`, a: `Application-level invariants plus JSON schema validation on the collection ($jsonSchema validator), unique indexes for uniqueness, transactions for cross-collection invariants, and background reconciliation jobs to detect orphans. Accept that referential integrity is your responsibility and design deletes as soft deletes or cascading jobs.` },
  { id: "mo32", c: "MongoDB", d: "Hard", q: `Design the data model for a chat application in MongoDB.`, a: `conversations (participants array indexed, lastMessage denormalised for the list view, updatedAt indexed for sorting), messages (conversationId + createdAt compound index, cursor pagination on _id), and per-user unread counters. Do not embed messages in the conversation — unbounded growth. Bucket messages per N if volume is extreme. Use change streams or a socket layer with a Redis pub/sub backplane for fan-out.` },

  // ======================== AUTH & SECURITY ================================
  { id: "au1", c: "Auth & Security", d: "Medium", q: `Sessions vs JWT — trade-offs and what you would pick.`, a: `Sessions are server-side state: easy to revoke instantly, small cookie, but need a shared store (Redis) across replicas. JWTs are stateless and verifiable without a lookup, but cannot be revoked before expiry without a blocklist, and grow with claims. Common production answer: short-lived access JWT (5-15 min) plus a rotating refresh token stored server-side so revocation is real.` },
  { id: "au2", c: "Auth & Security", d: "Medium", q: `What is inside a JWT and how is it verified?`, a: `Base64url header.payload.signature. The header names the algorithm, the payload holds claims (sub, exp, iat, iss, aud, custom), and the signature is HMAC (HS256) or asymmetric (RS256/ES256). Verification recomputes/checks the signature and validates exp, nbf, iss and aud. The payload is signed, not encrypted — never put secrets in it.` },
  { id: "au3", c: "Auth & Security", d: "Hard", q: `Name the classic JWT vulnerabilities.`, a: `alg: none acceptance; algorithm confusion where an RS256 public key is used as an HMAC secret; weak HMAC secrets brute-forced offline; missing exp or aud checks; trusting the kid header to load a key path; storing tokens in localStorage where XSS steals them; and no revocation path. Always pin the expected algorithm explicitly in the verify call.` },
  { id: "au4", c: "Auth & Security", d: "Medium", q: `Where should you store tokens in a browser?`, a: `httpOnly, secure, sameSite cookies are safest against XSS since JS cannot read them, but they need CSRF protection. localStorage is readable by any injected script, so one XSS is a full account takeover. A common middle ground: refresh token in an httpOnly cookie, access token in memory only, re-fetched on load.` },
  { id: "au5", c: "Auth & Security", d: "Medium", q: `Explain refresh token rotation and reuse detection.`, a: `Each refresh issues a new refresh token and invalidates the old one. If an already-used token is presented, that means it was stolen and replayed, so you revoke the entire token family and force re-login. Store the family/lineage id server-side; without rotation, a leaked refresh token is a permanent key.` },
  { id: "au6", c: "Auth & Security", d: "Medium", q: `What is CSRF and how do you prevent it?`, a: `The browser attaches cookies automatically, so a third-party site can trigger a state-changing request as the logged-in user. Defences: SameSite=Lax or Strict cookies (blocks most of it), synchroniser tokens or double-submit cookies, checking Origin/Referer, and never using GET for state changes. Token-in-header auth is not vulnerable because the header is not sent automatically.` },
  { id: "au7", c: "Auth & Security", d: "Medium", q: `What is XSS and how do you defend against it?`, a: `Injecting script into a page. Stored, reflected and DOM-based variants. Defences: contextual output encoding, never dangerouslySetInnerHTML with untrusted input (sanitise with DOMPurify), a strict Content-Security-Policy with nonces, httpOnly cookies to limit the blast radius, and validating URLs to block javascript: schemes. React escapes text by default, which covers the common case but not href/srcdoc/innerHTML.` },
  { id: "au8", c: "Auth & Security", d: "Medium", q: `Walk through the OAuth 2.0 authorization code flow with PKCE.`, a: `The client redirects to the authorisation server with a code_challenge derived from a random verifier. The user authenticates and consents; the server redirects back with a short-lived code and the state parameter. The client exchanges code plus code_verifier at the token endpoint for tokens. PKCE prevents interception of the code by a malicious app; state prevents CSRF on the callback. Implicit flow is deprecated.` },
  { id: "au9", c: "Auth & Security", d: "Medium", q: `Difference between OAuth 2.0 and OpenID Connect.`, a: `OAuth is an authorisation framework — it grants a client access to resources. OIDC is an identity layer on top that adds an ID token (a JWT describing the user), a userinfo endpoint, and standard scopes. Using an access token to "log a user in" is the classic misuse; the ID token is what proves identity.` },
  { id: "au10", c: "Auth & Security", d: "Medium", q: `How do you design role-based access control that scales?`, a: `Roles grant permissions, permissions guard actions, and code checks permissions rather than role names, so adding a role does not require code changes. Add resource-level rules (owner, team, tenant) evaluated in the service layer. Keep a single policy module, cover it with tests, and log denials. Never rely on hiding UI — the API must enforce it.` },
  { id: "au11", c: "Auth & Security", d: "Medium", q: `What are the OWASP Top 10 categories you can name and defend?`, a: `Broken access control, cryptographic failures, injection, insecure design, security misconfiguration, vulnerable and outdated components, identification and authentication failures, software and data integrity failures, security logging and monitoring failures, SSRF. Broken access control is number one and is exactly the IDOR class of bug — pick one you have actually prevented and describe how.` },
  { id: "au12", c: "Auth & Security", d: "Medium", q: `What is an IDOR and how do you prevent it?`, a: `Insecure direct object reference: /loans/123 returns another tenant's loan because the handler only checks that you are logged in. Prevent by scoping every query to the caller (findOne({ _id, ownerId: user.id })), enforcing in a repository layer rather than per route, using non-guessable ids as defence in depth, and writing tests that call another user's resource and expect 403/404.` },
  { id: "au13", c: "Auth & Security", d: "Medium", q: `How do you handle secrets and key rotation?`, a: `Secrets live in a manager (Vault, AWS Secrets Manager, Kubernetes secrets with encryption at rest), injected at runtime, never in git or the image. Rotate by supporting two valid keys at once: publish a key id, verify against both during the overlap, then retire the old one. Scan the repo history with gitleaks and revoke anything that ever leaked.` },
  { id: "au14", c: "Auth & Security", d: "Medium", q: `What security headers should a web app send?`, a: `Content-Security-Policy, Strict-Transport-Security with a long max-age, X-Content-Type-Options: nosniff, Referrer-Policy, X-Frame-Options or CSP frame-ancestors, Permissions-Policy, and Cross-Origin-Opener/Resource policies where relevant. helmet sets sane defaults, but CSP always needs tuning per app.` },
  { id: "au15", c: "Auth & Security", d: "Hard", q: `What is SSRF and how do you defend a service that fetches user-supplied URLs?`, a: `The server is tricked into calling internal addresses — cloud metadata endpoints, internal admin services. Defences: allowlist of schemes and hosts, resolve DNS and block private/link-local ranges (re-check after redirects to stop DNS rebinding), disable redirects or validate each hop, use a dedicated egress proxy, and block the metadata IP at the network layer.` },
  { id: "au16", c: "Auth & Security", d: "Medium", q: `How do you protect a login endpoint from brute force and credential stuffing?`, a: `Rate limit by IP and by account with progressive delays, lock or challenge after repeated failures, add CAPTCHA on suspicion, enforce MFA, check passwords against known-breach lists, use a slow hash, return identical responses and timing for unknown user versus wrong password, and alert on spikes of failed logins across many accounts.` },
  { id: "au17", c: "Auth & Security", d: "Medium", q: `What is the difference between encryption, hashing and encoding?`, a: `Encoding (base64) is reversible and offers no security. Hashing is one-way — used for passwords (slow, salted) and integrity (fast, SHA-256). Encryption is reversible with a key: symmetric (AES-GCM) for data at rest, asymmetric (RSA/ECC) for key exchange and signatures. Calling base64 "encryption" is an instant red flag.` },
  { id: "au18", c: "Auth & Security", d: "Medium", q: `How do you handle PII and compliance concerns in a fintech app?`, a: `Classify data, minimise collection, encrypt in transit and at rest, mask in logs and UI, tokenise identifiers where possible, restrict access with least privilege and audit trails, define retention and deletion, and keep an immutable audit log of who viewed or changed sensitive records. Know your regulator's requirements (RBI/DPDP in India) at least at a high level.` },
  { id: "au19", c: "Auth & Security", d: "Medium", q: `What is MFA and what are the trade-offs between factor types?`, a: `TOTP apps are cheap and offline but phishable. SMS OTP has wide reach but is vulnerable to SIM swap and interception. Push approval is user-friendly but suffers MFA fatigue attacks. WebAuthn/passkeys are phishing-resistant because the credential is bound to the origin — the strongest option. Always provide recovery codes and rate-limit verification attempts.` },
  { id: "au20", c: "Auth & Security", d: "Hard", q: `How do you secure a mobile/hybrid app that ships to users' devices?`, a: `Assume the bundle is readable: no secrets in the app, no client-side authorisation decisions. Use certificate pinning where feasible, store tokens in the OS keystore/keychain rather than plain storage, detect rooted devices for high-risk actions, enable code obfuscation, sign releases and protect the keystore, and put a server-side kill switch and minimum-version check in place.`, t: `If you have audited env vars inside an unpacked APK, that is a strong concrete story here.` },
  { id: "au21", c: "Auth & Security", d: "Medium", q: `How do you implement "log out from all devices"?`, a: `Keep a server-side session/token registry keyed by user with device metadata, and delete the family on request. With stateless JWTs, store a per-user tokenVersion or a "not valid before" timestamp; bump it on logout-all and reject any token issued earlier. Short access-token lifetimes keep the window small.` },
  { id: "au22", c: "Auth & Security", d: "Medium", q: `What is the principle of least privilege in an application and infra sense?`, a: `Every identity — user, service account, CI job, DB user — gets only the permissions it needs, scoped to the resources it touches, ideally time-bound. In practice: read-only DB users for reporting, per-service IAM roles instead of one shared key, no wildcard permissions in production, and regular access reviews. It is the single control that most limits blast radius when something is compromised.` },

  // ==================== BROWSER, PERFORMANCE & FRONTEND ====================
  { id: "fe1", c: "Browser & Perf", d: "Easy", q: `What happens when you type a URL and press enter?`, a: `DNS resolution (cache, resolver, authoritative), TCP handshake, TLS handshake (or QUIC for HTTP/3), HTTP request, server response, browser parses HTML into the DOM, fetches CSS/JS (render-blocking unless deferred), builds the CSSOM, forms the render tree, then layout, paint and composite. JS executes, hydration runs, and further data fetches happen. Interviewers use this to probe depth anywhere along the chain.` },
  { id: "fe2", c: "Browser & Perf", d: "Medium", q: `Explain the critical rendering path and how to optimise it.`, a: `HTML -> DOM, CSS -> CSSOM, both -> render tree -> layout -> paint -> composite. Optimise by inlining critical CSS and deferring the rest, using defer/async on scripts, preloading key fonts and the LCP image, avoiding synchronous layout reads inside write loops, and reducing the number of render-blocking resources.` },
  { id: "fe3", c: "Browser & Perf", d: "Medium", q: `What are the Core Web Vitals and how do you improve each?`, a: `LCP (largest contentful paint) — improve server response, preload the hero image, avoid lazy-loading it, cut render-blocking resources. INP (interaction to next paint, replaced FID) — break up long tasks, defer non-urgent work, reduce JS. CLS (cumulative layout shift) — reserve dimensions for images and ads, avoid inserting content above existing content, use font-display swap with matched metrics.` },
  { id: "fe4", c: "Browser & Perf", d: "Medium", q: `How do you reduce JavaScript bundle size?`, a: `Analyse first (webpack-bundle-analyzer, source-map-explorer). Then: route-level code splitting, dynamic imports for heavy widgets, tree-shakeable ESM libraries, replacing heavy dependencies (moment -> date-fns, lodash -> per-method imports), dropping polyfills for unsupported browsers via browserslist, and moving work server-side. Set a bundle-size budget in CI so regressions are caught in the PR.` },
  { id: "fe5", c: "Browser & Perf", d: "Medium", q: `Explain reflow vs repaint and how to avoid layout thrashing.`, a: `Reflow (layout) recalculates geometry and is expensive; repaint redraws pixels without geometry change; compositing only moves existing layers. Layout thrashing is alternating reads (offsetHeight, getBoundingClientRect) and writes in a loop, forcing synchronous layout each time. Batch reads then writes, or use requestAnimationFrame. Animate transform and opacity, which are composited, not top/left/width.` },
  { id: "fe6", c: "Browser & Perf", d: "Medium", q: `How does browser caching work for a deployed SPA?`, a: `Hashed asset filenames get Cache-Control: immutable with a one-year max-age, so a new build is a new URL and never serves stale JS. index.html is served with no-cache so the browser revalidates and picks up the new asset references. CDN caching sits in front, with cache invalidation on deploy for the HTML. Mismatch here is why users see a blank page after a deploy.` },
  { id: "fe7", c: "Browser & Perf", d: "Medium", q: `What are service workers and what can go wrong with them?`, a: `A proxy between the page and the network enabling offline caching, background sync and push. Risks: a bad service worker is sticky and can serve a broken cached app to returning users, so always ship an update/skipWaiting path and a kill switch. Cache strategies: cache-first for hashed assets, network-first for HTML and API, stale-while-revalidate for semi-fresh data.` },
  { id: "fe8", c: "Browser & Perf", d: "Medium", q: `Compare localStorage, sessionStorage, cookies and IndexedDB.`, a: `localStorage: ~5MB, synchronous (blocks the main thread), persists, same-origin, readable by JS. sessionStorage: same but per-tab. Cookies: small, sent on every matching request, can be httpOnly and secure, the only one usable by the server. IndexedDB: async, large, structured, transactional — the right choice for offline data and caches.` },
  { id: "fe9", c: "Browser & Perf", d: "Medium", q: `What is the difference between CSS Grid and Flexbox, and when do you use each?`, a: `Flexbox is one-dimensional — distributing space along a row or column; ideal for toolbars, button groups and card internals. Grid is two-dimensional with explicit rows and columns, named areas, and content that can be placed independently of source order — ideal for page layout and complex dashboards. They compose: a grid page with flex components.` },
  { id: "fe10", c: "Browser & Perf", d: "Medium", q: `Explain CSS specificity, the cascade, and how modern tools sidestep it.`, a: `Specificity is inline > id > class/attribute/pseudo-class > element, with later rules winning on ties and !important overriding (avoid it). CSS Modules, styled-components and Tailwind sidestep global conflicts by scoping or by using flat utility classes of equal specificity, which is why they scale better across teams. Cascade layers (@layer) now give explicit ordering control.` },
  { id: "fe11", c: "Browser & Perf", d: "Medium", q: `How do you make a UI accessible?`, a: `Semantic HTML first — a real button gets keyboard and screen-reader behaviour free. Then: labels tied to inputs, visible focus, logical tab order, focus trapping and restoration in modals, ARIA only when semantics fall short, sufficient colour contrast, live regions for async updates, and respecting prefers-reduced-motion. Test with keyboard only and with a screen reader, plus axe in CI.` },
  { id: "fe12", c: "Browser & Perf", d: "Medium", q: `What is responsive design beyond media queries?`, a: `Fluid type with clamp(), intrinsic layouts with minmax and auto-fit, container queries so a component responds to its own space rather than the viewport, responsive images with srcset/sizes and modern formats, and respecting user preferences (reduced motion, dark mode, font scaling). Mobile-first means writing the base styles for small screens and enhancing upward.` },
  { id: "fe13", c: "Browser & Perf", d: "Medium", q: `How do you optimise images on the web?`, a: `Serve AVIF/WebP with fallbacks, size them for the actual layout with srcset and sizes, set width/height or aspect-ratio to prevent CLS, lazy-load below-the-fold images while eagerly loading the LCP image with fetchpriority="high", and use a CDN with on-the-fly resizing. Images are usually the largest byte contributor on a page.` },
  { id: "fe14", c: "Browser & Perf", d: "Hard", q: `How would you diagnose a page that is slow only for some users?`, a: `Split real-user monitoring by device class, network type, geography and app version — synthetic lab tests hide this. Common causes: low-end CPUs choking on hydration and long tasks, high-latency networks amplifying request waterfalls, distant regions without a nearby CDN edge, and cold caches on first visit. Fix the p75 mobile experience, not your laptop's.` },
  { id: "fe15", c: "Browser & Perf", d: "Medium", q: `What is the difference between SSR, SSG, ISR and CSR?`, a: `CSR ships an empty shell and renders in the browser — fast to deploy, poor first paint and SEO. SSR renders per request — fresh and SEO-friendly, higher server cost and TTFB. SSG builds at deploy time — fastest and cheapest, stale until rebuild. ISR regenerates pages on demand after a revalidation window, combining static speed with freshness. Pick per route, not per app.` },
  { id: "fe16", c: "Browser & Perf", d: "Medium", q: `Explain Next.js App Router fundamentals.`, a: `File-system routing with layouts that persist across navigation, server components by default with "use client" for interactivity, loading.js and error.js as Suspense/error boundaries, route handlers for APIs, server actions for mutations, and fetch-level caching with revalidate and tags. The mental shift is that data fetching lives in the component that needs it, on the server.` },
  { id: "fe17", c: "Browser & Perf", d: "Medium", q: `How do you handle SEO in a JavaScript application?`, a: `Server-render or pre-render content that must be indexed, provide unique titles and meta descriptions per route, use canonical URLs, structured data (JSON-LD), a sitemap and robots.txt, real anchor tags for navigation, and fast Core Web Vitals. Verify with Search Console's URL inspection rather than assuming the crawler runs your JS.` },
  { id: "fe18", c: "Browser & Perf", d: "Medium", q: `What are Web Workers and when have you needed one?`, a: `Background threads without DOM access, communicating via postMessage. Use for parsing large CSV/JSON, image processing, crypto, heavy filtering or search indexing — anything that would otherwise block interaction. Cost: serialisation overhead and no shared DOM, so keep the interface coarse-grained.` },
  { id: "fe19", c: "Browser & Perf", d: "Medium", q: `Explain how bundlers work and how Vite differs from Webpack.`, a: `A bundler builds a module graph from an entry, transforms with loaders/plugins, tree-shakes, splits chunks and emits assets. Webpack bundles for dev too, so startup grows with app size. Vite serves native ESM in dev with esbuild-based transforms for near-instant startup and HMR, and uses Rollup for production builds. Turbopack and Rspack chase the same goal with Rust.` },
  { id: "fe20", c: "Browser & Perf", d: "Medium", q: `What is tree shaking and why does it sometimes fail?`, a: `Dead-code elimination based on static ESM imports. It fails with CommonJS modules, with side-effectful modules not marked sideEffects: false in package.json, with barrel files that re-export everything, and with dynamic property access on a namespace import. Import specific paths and check the analyser output rather than assuming.` },
  { id: "fe21", c: "Browser & Perf", d: "Medium", q: `How do you handle client-side error monitoring?`, a: `Sentry or similar with source maps uploaded at build time so stack traces are readable, release tagging so you can tie a spike to a deploy, user context and breadcrumbs, sampling to control cost, and alerting on new-issue and error-rate thresholds. Add window.onerror and unhandledrejection handlers, plus React error boundaries for render failures.` },
  { id: "fe22", c: "Browser & Perf", d: "Hard", q: `How would you implement offline support for a field-use app?`, a: `Cache the app shell with a service worker, store data in IndexedDB, queue mutations locally with a client-generated id, and sync when connectivity returns with retry and conflict resolution (last-write-wins, version vectors, or server-authoritative merge). Show sync status explicitly, and make every mutation idempotent server-side because the queue will retry.` },
  { id: "fe23", c: "Browser & Perf", d: "Medium", q: `What is the difference between HTTP/1.1, HTTP/2 and HTTP/3?`, a: `HTTP/1.1: one request per connection at a time, so browsers open ~6 and developers concatenate assets. HTTP/2: multiplexed streams over one TCP connection, header compression, server push (now deprecated) — but a lost packet stalls all streams (TCP head-of-line blocking). HTTP/3 runs over QUIC/UDP, removing that blocking and speeding up connection setup, especially on lossy mobile networks.` },
  { id: "fe24", c: "Browser & Perf", d: "Medium", q: `Explain the same-origin policy and the ways to legitimately cross origins.`, a: `Origin is scheme + host + port; scripts cannot read cross-origin responses or DOM by default. Legitimate crossings: CORS for XHR/fetch, postMessage between windows/iframes with an origin check, CORS-enabled subresources with crossorigin attributes, and server-side proxying. Never use "*" for credentialed requests, and always validate the origin in a postMessage handler.` },
  { id: "fe25", c: "Browser & Perf", d: "Medium", q: `How do you monitor real user performance?`, a: `The web-vitals library reporting LCP, INP, CLS and TTFB to your analytics endpoint, segmented by route, device and connection; Long Animation Frames and the PerformanceObserver API for long tasks; and Resource Timing for asset waterfalls. Track p75, not averages — averages hide the users who are actually suffering.` },
  { id: "fe26", c: "Browser & Perf", d: "Hard", q: `What is a request waterfall and how do you eliminate one?`, a: `Sequentially dependent requests where each starts only after the previous resolves — component A fetches, renders B, which fetches. Fix by hoisting data requirements (route loaders, server components fetching in parallel), issuing independent requests with Promise.all, preloading on hover/route intent, and using HTTP/2 multiplexing plus early hints. Check the Network panel's start times, not just durations.` },

  // =============================== TESTING =================================
  { id: "te1", c: "Testing", d: "Easy", q: `Explain the testing pyramid and how you apply it.`, a: `Many fast unit tests, fewer integration tests, very few end-to-end tests. Unit tests catch logic errors cheaply; integration tests catch wiring bugs (routes, DB, serialisation) which is where most real bugs live; E2E covers critical user journeys only, because they are slow and flaky. Some teams prefer the "testing trophy" with integration weighted heaviest — either framing is fine if you justify it.` },
  { id: "te2", c: "Testing", d: "Medium", q: `What makes a good unit test?`, a: `Fast, deterministic, isolated, and named after the behaviour it protects. It asserts on observable outcomes rather than internals, so refactoring does not break it. Arrange-Act-Assert structure, one logical assertion per test, no shared mutable state between tests, and no dependence on execution order or wall-clock time.` },
  { id: "te3", c: "Testing", d: "Medium", q: `Mock vs stub vs spy vs fake — do you know the difference?`, a: `A stub returns canned values. A spy records calls while keeping real behaviour. A mock is a stub with assertions about how it was called. A fake is a working lightweight implementation (in-memory repository). Prefer fakes and real dependencies where fast; heavy mocking couples tests to implementation and lets broken code pass.` },
  { id: "te4", c: "Testing", d: "Medium", q: `How do you test code that depends on time, randomness or the network?`, a: `Inject them. Use fake timers (jest.useFakeTimers, vi.setSystemTime) for time, seed or inject the random source, and intercept HTTP at the network layer with MSW so the code under test uses real fetch. Avoid sleeping in tests — wait for a condition instead, which is the main cure for flakiness.` },
  { id: "te5", c: "Testing", d: "Medium", q: `What is your view on code coverage targets?`, a: `Coverage tells you what was executed, not what was verified — 100% coverage with weak assertions proves nothing. Useful as a regression signal and to find untested critical paths; harmful as a hard gate that pushes people to write trivial tests. Better: require tests on changed lines and track coverage on the modules that matter (payments, auth, calculations).` },
  { id: "te6", c: "Testing", d: "Medium", q: `How do you test a REST API end to end?`, a: `Spin the app with a real test database (testcontainers or an ephemeral instance), seed fixtures per test, use supertest against the app instance, and reset with transactions or truncation between tests. Cover auth (401/403), validation errors, pagination boundaries, idempotency and concurrency, not just 200s.` },
  { id: "te7", c: "Testing", d: "Medium", q: `How do you handle flaky tests?`, a: `Treat a flake as a real bug: quarantine it so it stops blocking the pipeline, but track and fix it. Common causes: waiting on timeouts instead of conditions, shared state or database rows between tests, real network calls, animation timing, and test order dependence. Blanket retries hide product race conditions that users will eventually hit.` },
  { id: "te8", c: "Testing", d: "Medium", q: `What is snapshot testing good and bad at?`, a: `Good for small, stable serialisable output — a formatting function, a config object, a tiny component. Bad for large component trees: diffs are unreadable, so people run --u reflexively and the test stops catching anything. Prefer explicit assertions on the behaviour that matters.` },
  { id: "te9", c: "Testing", d: "Medium", q: `How would you add tests to a legacy module with zero coverage?`, a: `Start with characterisation tests that lock in current behaviour at the boundary (inputs to outputs), so you have a safety net before refactoring. Then extract seams — inject dependencies — and unit-test the extracted pieces. Prioritise the paths with the highest cost of failure, not the easiest to test.`, t: `If you have retrofitted tests onto an untested workflow engine, this is your story — describe the seam you cut first.` },
  { id: "te10", c: "Testing", d: "Medium", q: `What is E2E testing with Playwright/Cypress and how do you keep it stable?`, a: `Drive a real browser through user journeys. Stability rules: select by role or test id rather than CSS classes, rely on auto-waiting for conditions instead of fixed sleeps, seed data via API rather than through the UI, run tests independently and in parallel, isolate state per test, and record traces/videos on failure for debugging in CI.` },
  { id: "te11", c: "Testing", d: "Hard", q: `What is contract testing and when is it worth it?`, a: `Consumers publish expectations of a provider's API, and the provider verifies them in its own CI (Pact), so a breaking change fails before deploy. Worth it when several teams own separate services and full E2E environments are slow or unreliable. In a monolith with one team, an OpenAPI schema check in CI usually gets you most of the value.` },
  { id: "te12", c: "Testing", d: "Medium", q: `How do you test React hooks and context?`, a: `renderHook from React Testing Library, with act for updates and a wrapper providing the required providers. Assert on the returned values and on side effects (network calls intercepted by MSW). For context, render a small consumer component and test the observable behaviour rather than reaching into the context value directly.` },
  { id: "te13", c: "Testing", d: "Medium", q: `What is TDD and do you actually use it?`, a: `Red-green-refactor: write a failing test, make it pass minimally, then refactor. It works best for well-specified logic with clear inputs and outputs — parsers, calculations, business rules. It is awkward for exploratory UI work. An honest answer that says where you apply it and where you do not is stronger than claiming you always TDD.` },
  { id: "te14", c: "Testing", d: "Medium", q: `How do you test a background job or queue consumer?`, a: `Unit-test the handler as a pure function of the job payload. Integration-test with an in-memory or containerised broker, asserting on retry behaviour, idempotency (run the same job twice, expect one effect), dead-letter routing after max attempts, and correct acknowledgement on partial failure.` },

  // ================== DEPLOYMENT, DOCKER, CI/CD & INFRA ====================
  { id: "dp1", c: "Deployment & DevOps", d: "Easy", q: `What actually happens when you deploy a MERN app to production?`, a: `Build the React app into static assets and serve them from a CDN or Nginx; build the Node API into an image; run the API behind a reverse proxy/load balancer with TLS terminated at the edge; connect to a managed Mongo cluster over a private network; inject config through environment variables; run health checks; roll out gradually; and watch logs, metrics and error rates. Everything else in this section is a detail of that shape.` },
  { id: "dp2", c: "Deployment & DevOps", d: "Easy", q: `What problem does Docker solve, and what is the difference between an image and a container?`, a: `It packages the app with its dependencies and OS userland so it runs identically everywhere, removing "works on my machine". An image is an immutable layered filesystem plus metadata; a container is a running instance of it with a writable layer, isolated by namespaces and limited by cgroups. Containers share the host kernel, unlike VMs.` },
  { id: "dp3", c: "Deployment & DevOps", d: "Medium", q: `How do you write a good Dockerfile for a Node app?`, a: `Multi-stage: build with a full image, then copy only the built output into a slim/alpine runtime. Copy package.json and lockfile first and run npm ci so the dependency layer caches. Use --omit=dev in the runtime stage, add a .dockerignore (node_modules, .git, .env), run as a non-root user, set NODE_ENV=production, expose a health endpoint, and use exec-form CMD so signals reach the process.` },
  { id: "dp4", c: "Deployment & DevOps", d: "Medium", q: `Why does layer ordering matter in a Dockerfile?`, a: `Each instruction creates a layer, and a change invalidates every layer after it. Copying the whole source before installing dependencies means every code change reinstalls node_modules. Copy manifests, install, then copy source. Use BuildKit cache mounts for the npm cache and you cut minutes off CI.` },
  { id: "dp5", c: "Deployment & DevOps", d: "Medium", q: `How do you handle secrets in Docker builds and runtime?`, a: `Never with ARG or COPY of a .env, because build args and layers are inspectable in the image history. Use BuildKit secret mounts for build-time credentials, and inject runtime secrets as environment variables or mounted files from a secrets manager. Scan images with Trivy and keep base images patched.` },
  { id: "dp6", c: "Deployment & DevOps", d: "Medium", q: `What is docker-compose used for and where does it stop being enough?`, a: `Defining a multi-container local environment — API, Mongo, Redis, Nginx — with networks, volumes and dependency order. It is excellent for development and small single-host deployments. It stops being enough when you need multi-node scheduling, rolling updates with health gating, autoscaling and self-healing — that is Kubernetes or a managed platform.` },
  { id: "dp7", c: "Deployment & DevOps", d: "Medium", q: `Explain the PID 1 / signal handling problem in containers.`, a: `The process started by CMD is PID 1, which does not get default signal handlers and does not reap zombies. If you launch via a shell (shell-form CMD) the shell becomes PID 1 and swallows SIGTERM, so the orchestrator waits the full grace period then SIGKILLs — dropping in-flight requests. Use exec form, handle SIGTERM in Node, and add tini or --init when you need a reaper.` },
  { id: "dp8", c: "Deployment & DevOps", d: "Medium", q: `What are Kubernetes pods, deployments and services?`, a: `A pod is one or more co-located containers sharing a network namespace — the smallest schedulable unit. A Deployment manages a ReplicaSet to keep N pods running and performs rolling updates. A Service gives a stable virtual IP and DNS name that load-balances across matching pods. Ingress routes external HTTP traffic to services with TLS.` },
  { id: "dp9", c: "Deployment & DevOps", d: "Medium", q: `Difference between liveness, readiness and startup probes.`, a: `Liveness: is the process healthy — failing restarts the pod. Readiness: can it serve traffic right now — failing removes it from the service endpoints without restarting. Startup: gives slow-booting apps time before liveness kicks in. Pointing liveness at a check that depends on the database is a classic mistake: a DB blip then restart-loops every pod.`, t: `That liveness/DB mistake is a great answer to "tell me an outage you learned from".` },
  { id: "dp10", c: "Deployment & DevOps", d: "Medium", q: `Compare rolling, blue-green and canary deployments.`, a: `Rolling replaces instances gradually — no extra cost, but two versions run at once so the API and DB must be compatible. Blue-green runs a full second environment and switches traffic at once — instant rollback, double the resources. Canary sends a small percentage to the new version and watches metrics before ramping — safest, needs good observability and traffic splitting.` },
  { id: "dp11", c: "Deployment & DevOps", d: "Hard", q: `How do you deploy a schema change with zero downtime?`, a: `Expand and contract. Expand: add the new field or column as nullable/optional and deploy code that writes both and reads the old. Backfill in batches. Switch reads to the new field. Then contract: stop writing the old field and drop it in a later release. Never combine a breaking migration with the code that depends on it in one deploy — you cannot roll back.` },
  { id: "dp12", c: "Deployment & DevOps", d: "Medium", q: `What goes in a CI/CD pipeline for a MERN app?`, a: `On PR: install with a cached lockfile, lint, typecheck, unit and integration tests, build, bundle-size check, security audit. On merge: build a versioned image, push to a registry, run migrations, deploy to staging, run smoke/E2E tests, then promote to production with a gradual rollout and automatic rollback on error-rate alerts. Tag the release and upload source maps.` },
  { id: "dp13", c: "Deployment & DevOps", d: "Medium", q: `How do you manage environment variables across environments?`, a: `Twelve-factor: config in the environment, not in code. Keep a committed .env.example listing every required key, validate at boot with a schema so a missing var fails fast, source real values from the platform or a secrets manager, and never reuse production credentials in staging. Remember that anything prefixed for the client bundle (VITE_, NEXT_PUBLIC_) is public.`, t: `Common trap question: "is NEXT_PUBLIC_API_KEY safe?" — no, it is baked into the JS anyone can read.` },
  { id: "dp14", c: "Deployment & DevOps", d: "Medium", q: `What does Nginx do in front of a Node app?`, a: `TLS termination, HTTP/2, static asset serving with caching headers, gzip/brotli compression, reverse proxying with upstream health checks and load balancing, request size limits, basic rate limiting, and SPA fallback (try_files ... /index.html). It also sets X-Forwarded-For and X-Forwarded-Proto, which Node must trust via trust proxy.` },
  { id: "dp15", c: "Deployment & DevOps", d: "Medium", q: `How do you configure Nginx for a React SPA plus an API on the same domain?`, a: `Serve the build directory as root with try_files $uri $uri/ /index.html so client routes resolve. Give hashed assets a long immutable cache and index.html no-cache. Proxy /api to the Node upstream with proxy_pass, forwarding Host and the X-Forwarded headers, and enable proxy upgrade headers if you use WebSockets. Same origin means no CORS and cookies just work.` },
  { id: "dp16", c: "Deployment & DevOps", d: "Medium", q: `What is a CDN and what should it cache?`, a: `Geographically distributed edge caches that cut latency and origin load. Cache hashed static assets aggressively, images with transformation at the edge, and public GET API responses with a short s-maxage plus stale-while-revalidate. Never cache authenticated responses without Vary: Authorization or a cache key that includes the user — that is how one user sees another's data.` },
  { id: "dp17", c: "Deployment & DevOps", d: "Medium", q: `Compare deploying to a VM, a container platform, and serverless.`, a: `VM/EC2: full control, you own patching, scaling and process supervision. Container platform (ECS, Kubernetes, Cloud Run, Render): image-based, orchestrated scaling and health management, moderate ops. Serverless (Lambda, Vercel functions): no servers and scale-to-zero, but cold starts, execution limits, connection-pool pressure on databases, and vendor-shaped code. Choose by team size and traffic shape, not fashion.` },
  { id: "dp18", c: "Deployment & DevOps", d: "Hard", q: `Why are database connections a problem in serverless, and how do you fix it?`, a: `Each concurrent invocation is its own process, so N concurrent requests can open N pools and exhaust the database's connection limit. Fixes: a connection proxy (RDS Proxy, PgBouncer, Mongo's data API), reusing the client across warm invocations by declaring it outside the handler, capping pool size at 1-5, and setting aggressive idle timeouts.` },
  { id: "dp19", c: "Deployment & DevOps", d: "Medium", q: `What is horizontal vs vertical scaling, and what breaks when you go horizontal?`, a: `Vertical is a bigger machine — simple, limited, single point of failure. Horizontal is more instances behind a load balancer — elastic and fault tolerant. Going horizontal breaks anything holding local state: in-memory sessions, in-memory rate limits and caches, local file uploads, node-cron jobs running per instance, and WebSocket rooms. Externalise all of it (Redis, S3, a queue with a leader lock).` },
  { id: "dp20", c: "Deployment & DevOps", d: "Medium", q: `How do you decide autoscaling rules?`, a: `Scale on a metric that reflects saturation for your workload — for Node that is often concurrent requests, event-loop lag or p95 latency rather than CPU, since I/O-bound services stay at low CPU while queueing. Set sensible min replicas to absorb spikes, a cooldown to prevent flapping, and headroom for the time it takes a pod to become ready. Load-test to find the knee first.` },
  { id: "dp21", c: "Deployment & DevOps", d: "Medium", q: `What is infrastructure as code and why does it matter?`, a: `Declaring infrastructure in version-controlled files (Terraform, Pulumi, CloudFormation) so environments are reproducible, reviewable and auditable. It gives you diffable plans before applying, disaster recovery by re-apply, and drift detection. Store state remotely with locking, never edit resources by hand afterwards, and keep secrets out of state files.` },
  { id: "dp22", c: "Deployment & DevOps", d: "Medium", q: `What are the four golden signals and what would you alert on?`, a: `Latency, traffic, errors, saturation. Alert on symptoms users feel — error rate above a threshold, p95 latency breach, availability drop — not on every CPU spike. Use SLOs with error budgets to decide when paging is justified, keep the number of paging alerts small enough to stay trustworthy, and route everything else to a dashboard.` },
  { id: "dp23", c: "Deployment & DevOps", d: "Medium", q: `Logs, metrics and traces — what is each for?`, a: `Logs are discrete events with detail, good for "what exactly happened to this request". Metrics are cheap aggregated time series, good for trends, dashboards and alerts. Traces follow one request across services with spans, good for "where did the 2 seconds go". Correlate them with a shared trace id; OpenTelemetry is the vendor-neutral way to emit all three.` },
  { id: "dp24", c: "Deployment & DevOps", d: "Medium", q: `How do you do zero-downtime deploys with a load balancer?`, a: `New instances must pass readiness before receiving traffic; old instances are drained — deregistered, given time to finish in-flight requests, then stopped. The app handles SIGTERM by failing readiness first, then closing the server. Keep the LB idle timeout below the app keep-alive timeout to avoid 502s, and make the two versions mutually compatible for the overlap window.` },
  { id: "dp25", c: "Deployment & DevOps", d: "Medium", q: `What is a feature flag and how does it change deployment?`, a: `A runtime switch that decouples deploy from release — you ship dark code and enable it for a cohort, ramp gradually, and kill it instantly without a rollback. Enables trunk-based development and A/B tests. Costs: flag debt, combinatorial testing, and stale flags. Set an owner and an expiry per flag and remove them after rollout.` },
  { id: "dp26", c: "Deployment & DevOps", d: "Medium", q: `How do you roll back safely?`, a: `Keep images immutable and versioned so rollback is redeploying the previous tag. Ensure schema changes are backwards-compatible so the old code still runs against the new database — this is what makes rollback possible at all. Practise it, automate it on alert thresholds, and keep the rollback path shorter than the debugging path.` },
  { id: "dp27", c: "Deployment & DevOps", d: "Medium", q: `What is Redis used for in a MERN deployment?`, a: `Shared cache for hot reads, session store, distributed rate limiting, job queue backing (BullMQ), pub/sub backplane for WebSockets across instances, and distributed locks. Key decisions: eviction policy and maxmemory, TTLs on everything, key naming conventions, and never treating it as a durable database without persistence and replication configured.` },
  { id: "dp28", c: "Deployment & DevOps", d: "Hard", q: `Explain cache invalidation strategies.`, a: `TTL is simplest and bounds staleness. Write-through updates the cache on write; cache-aside (lazy load) is the common default; write-behind batches writes and risks loss. Explicit invalidation by key or tag on mutation is precise but easy to miss. Watch for stampedes when a hot key expires — use a lock, jittered TTLs, or stale-while-revalidate.` },
  { id: "dp29", c: "Deployment & DevOps", d: "Medium", q: `How do you deploy a Capacitor/Cordova hybrid app and push updates?`, a: `Native builds are signed and distributed through the store, Firebase App Distribution, MDM, or a self-hosted APK. Web-layer changes can ship over the air (Capgo, CodePush-style) without a store review, but native plugin changes require a full build. Critical details: version the web bundle, verify integrity, detect a stuck or failed OTA and fall back, and keep a forced-update path for breaking API changes.`, t: `You have shipped exactly this — lead with the silent-failure detection design.` },
  { id: "dp30", c: "Deployment & DevOps", d: "Hard", q: `Why do release builds break when debug builds work on Android?`, a: `Release enables minification and shrinking (ProGuard/R8), which strips or renames classes reached only via reflection — Firebase, push notification receivers, JSON model classes — so you need keep rules. Release also enforces cleartext traffic restrictions unless a network security config permits it, uses a different signing key (breaking API key restrictions and OAuth signatures), and disables debug-only permissions and logging.` },
  { id: "dp31", c: "Deployment & DevOps", d: "Medium", q: `What is a monorepo and what tooling makes it work?`, a: `One repository holding several packages/apps with shared code and atomic cross-cutting changes. Tooling: workspaces (npm/pnpm/yarn), a task runner with a dependency graph and remote caching (Turborepo, Nx), and affected-only CI so a change to one app does not rebuild everything. Trade-offs: shared tooling and simpler refactors versus slower CI and access-control complexity.` },
  { id: "dp32", c: "Deployment & DevOps", d: "Medium", q: `Explain a sensible git branching strategy for a small product team.`, a: `Trunk-based with short-lived feature branches, PR review, CI gates, and release via tags or feature flags. Gitflow's long-lived develop/release branches create painful merges and slow releases for most product teams. Whatever you pick, define how hotfixes reach production and how they get back into the mainline.` },
  { id: "dp33", c: "Deployment & DevOps", d: "Medium", q: `What is the difference between git merge, rebase and squash, and when do you use each?`, a: `Merge preserves history and creates a merge commit — safe on shared branches. Rebase replays commits for a linear history — never rebase a branch others have pulled. Squash collapses a feature branch into one commit — clean mainline history, loses granular steps. Most teams squash-merge PRs and rebase locally to stay current.` },
  { id: "dp34", c: "Deployment & DevOps", d: "Medium", q: `How would you set up staging so it actually catches problems?`, a: `Same image, same infrastructure shape, same config mechanism as production, with anonymised production-like data volumes and the same third-party sandboxes. Run migrations there first, run smoke and E2E suites after deploy, and keep it genuinely used — a staging environment nobody trusts gets skipped, which is how untested changes reach production.` },
  { id: "dp35", c: "Deployment & DevOps", d: "Hard", q: `A deploy went out and error rates spiked. Walk me through your response.`, a: `Stop the bleeding first: roll back or disable the flag, then investigate. Confirm scope from dashboards (which routes, which regions, which version), check the release diff and recent config or migration changes, correlate with traces and error grouping, communicate status to stakeholders. Afterwards write a blameless postmortem with a timeline, contributing factors, and concrete action items with owners.` },
  { id: "dp36", c: "Deployment & DevOps", d: "Medium", q: `What is the difference between an ALB, an API gateway and a service mesh?`, a: `A load balancer distributes L4/L7 traffic across instances with health checks. An API gateway adds API concerns: auth, rate limiting, request transformation, routing by path, usage plans. A service mesh handles service-to-service traffic via sidecars — mTLS, retries, circuit breaking, traffic splitting and telemetry without app code changes. They solve different layers and often coexist.` },
  { id: "dp37", c: "Deployment & DevOps", d: "Medium", q: `How do you keep Docker images small and secure?`, a: `Multi-stage builds, slim or distroless base images, .dockerignore, no build toolchain in the runtime stage, pinned base image digests, non-root user, no secrets in layers, and vulnerability scanning in CI with a policy on severity. Smaller images pull faster, which directly shortens deploy and autoscale time.` },
  { id: "dp38", c: "Deployment & DevOps", d: "Medium", q: `What are resource requests and limits, and what happens when you get them wrong?`, a: `Requests drive scheduling and guarantee capacity; limits cap usage. Memory over the limit gets the container OOM-killed; CPU over the limit gets throttled, showing up as mysterious latency rather than errors. Too-high requests waste money and block scheduling; too-low requests get you evicted under pressure. Set them from observed p95 usage, not guesses.` },

  // ============================= SYSTEM DESIGN =============================
  { id: "sd1", c: "System Design", d: "Medium", q: `What framework do you use to answer any system design question?`, a: `1) Clarify functional and non-functional requirements. 2) Estimate scale — users, QPS, read/write ratio, payload size, storage growth. 3) Define the API surface. 4) Sketch the high-level architecture. 5) Design the data model and pick storage. 6) Deep dive on the hardest component. 7) Discuss bottlenecks, caching, scaling, failure modes. 8) State trade-offs explicitly. Never start drawing boxes before step 1.`, t: `At 2 years experience, they mostly test structure and reasoning, not exotic infrastructure.` },
  { id: "sd2", c: "System Design", d: "Medium", q: `Design a URL shortener.`, a: `API: POST /urls returns a short code, GET /:code redirects with 301/302. Generate codes with base62 of a distributed counter or a hash with collision retry; do not use a naive incrementing id if guessability matters. Store code -> long URL in a key-value store, cache hot codes in Redis, use 302 if you need click analytics (301 is cached by browsers). Scale reads with a CDN and read replicas; writes are tiny. Discuss custom aliases, expiry and abuse/malware checks.` },
  { id: "sd3", c: "System Design", d: "Medium", q: `Design a rate limiter.`, a: `Algorithms: fixed window (simple, boundary bursts), sliding window log (accurate, memory heavy), sliding window counter (good compromise), token bucket (allows bursts, standard choice), leaky bucket (smooths output). Implement in Redis with an atomic Lua script keyed by user or IP plus route. Return 429 with Retry-After and X-RateLimit headers. Discuss distributed accuracy versus latency, and failing open vs closed when Redis is down.` },
  { id: "sd4", c: "System Design", d: "Medium", q: `Design a notification system (email, SMS, push, in-app).`, a: `Producers publish events to a queue; a notification service resolves user preferences and templates, then fans out to channel-specific workers with provider adapters. Requirements: idempotency by event id, retries with backoff and a DLQ, per-user rate limits and quiet hours, template versioning, delivery status tracking via provider webhooks, and a fallback provider. Batch and digest to avoid spamming.` },
  { id: "sd5", c: "System Design", d: "Hard", q: `Design a real-time chat application.`, a: `WebSocket gateway layer (stateless, sticky or with a Redis pub/sub backplane) plus an API for history. Messages go to a durable store keyed by conversation and time, with cursor pagination. Delivery: client-generated message id for idempotency and optimistic UI, server acks, per-device read receipts, and an offline queue delivered on reconnect. Presence via heartbeats with TTL in Redis. Scale by sharding conversations and fanning out through pub/sub.` },
  { id: "sd6", c: "System Design", d: "Medium", q: `Design a news feed.`, a: `Fan-out on write (precompute each follower's timeline) gives fast reads but is expensive for celebrities; fan-out on read (query followed users at request time) is cheap to write but slow to read. Hybrid: fan out for normal users, pull for high-follower accounts. Cache timelines in Redis lists with a bounded length, paginate by cursor, and rank with a scoring service. Discuss consistency (eventual is fine) and backfill on follow.` },
  { id: "sd7", c: "System Design", d: "Medium", q: `Design a file upload and storage service.`, a: `Client requests a presigned URL and uploads directly to object storage, bypassing your servers. Metadata row records status, size, checksum and owner. Use multipart upload for large files with resume; validate content type by sniffing after upload; scan asynchronously; generate derivatives (thumbnails) in a worker; serve through a CDN with signed URLs for private files. Discuss quotas, lifecycle policies and orphan cleanup.` },
  { id: "sd8", c: "System Design", d: "Hard", q: `Design a payment or ledger flow.`, a: `Double-entry ledger: every transaction writes balanced debit and credit entries, append-only, never updated. Balances are derived (or maintained as a materialised snapshot with a checkpoint). Use idempotency keys on every write path, a state machine for transaction status, and reconciliation jobs against the provider's statement. Use a relational store with real transactions and store amounts as integer minor units. Discuss retries, webhooks arriving out of order, and eventual settlement.`, t: `Your fintech background makes this a question you should own — mention reconciliation and idempotency unprompted.` },
  { id: "sd9", c: "System Design", d: "Medium", q: `Design a document/KYC verification pipeline.`, a: `Upload to object storage -> queue a processing job -> extract with OCR or an LLM -> validate fields against the application -> route to auto-approve, manual review or reject -> emit status events. Needs: per-stage status persistence so retries resume rather than restart, provider timeouts and fallbacks, PII handling with encryption and access logs, a reviewer UI with audit trail, and confidence thresholds tuned against a labelled sample.` },
  { id: "sd10", c: "System Design", d: "Medium", q: `How do you design for high availability?`, a: `Remove single points of failure: multiple instances across availability zones, replicated data stores with automated failover, health-checked load balancing, and no local state. Add graceful degradation (serve cached or partial data when a dependency is down), timeouts, retries with backoff, circuit breakers and bulkheads. Define an SLO, then test with failure injection rather than hoping.` },
  { id: "sd11", c: "System Design", d: "Medium", q: `Explain the CAP theorem in practical terms.`, a: `During a network partition you must choose availability or consistency; when there is no partition you can have both plus low latency (which is what PACELC adds). Practically: a payments ledger chooses consistency and rejects writes rather than diverge; a feed or presence system chooses availability and reconciles later. The useful skill is deciding per feature, not per system.` },
  { id: "sd12", c: "System Design", d: "Medium", q: `What is eventual consistency and how do you make it acceptable to users?`, a: `Replicas converge over time, so a read right after a write may be stale. Make it tolerable with read-your-own-writes (route the user to the primary or serve their optimistic local copy), explicit pending states in the UI, monotonic reads via sticky routing, and clear messaging like "processing". The failure mode users hate is silent disappearance of their own action.` },
  { id: "sd13", c: "System Design", d: "Medium", q: `When would you introduce a message queue?`, a: `To decouple producers from consumers, absorb spikes, retry failures without blocking the user, fan out one event to many consumers, and run slow work outside the request. Costs: eventual consistency, ordering complexity, duplicate delivery (so handlers must be idempotent), and another system to operate and monitor. Do not add one for work that finishes in 50ms.` },
  { id: "sd14", c: "System Design", d: "Hard", q: `How do you guarantee a database write and a queue publish both happen?`, a: `Dual writes are unreliable — the process can die between them. Use the transactional outbox: write the event into an outbox table inside the same transaction as the business data, then a relay process (or change stream / CDC) publishes it and marks it sent. That gives at-least-once delivery with no lost events, so consumers must be idempotent.` },
  { id: "sd15", c: "System Design", d: "Medium", q: `Monolith vs microservices for a startup — what is your position?`, a: `Start with a well-modularised monolith: one deploy, one database, simple transactions and local calls, far faster to change. Split when you have real forcing functions — independent scaling needs, team ownership boundaries, or differing reliability requirements. Premature microservices trade a code problem for a distributed systems problem, and most 10-person teams lose that trade.` },
  { id: "sd16", c: "System Design", d: "Medium", q: `How would you design a search feature over a few million records?`, a: `Do not build it on LIKE queries. Index into a search engine (Elasticsearch/OpenSearch/Typesense) fed by change streams or an outbox, with analysers for stemming and synonyms, typo tolerance, and field boosting. Handle relevance tuning, filters and facets, pagination via search_after rather than deep offsets, and reindexing with an alias swap for zero downtime.` },
  { id: "sd17", c: "System Design", d: "Medium", q: `Design an analytics/reporting dashboard over operational data.`, a: `Do not run heavy aggregations against the production primary. Options in increasing order: read replicas with a dedicated read preference, precomputed rollups refreshed on a schedule ($merge or materialised views), or a warehouse fed by CDC. Serve the dashboard from precomputed aggregates with a freshness indicator, and cache expensive queries with TTL keyed by filter combination.` },
  { id: "sd18", c: "System Design", d: "Hard", q: `How do you handle distributed locking, and what are the pitfalls?`, a: `SET key value NX PX ttl in Redis with a unique token, released with a Lua compare-and-delete so you never release someone else's lock. Pitfalls: the TTL expiring while you still hold the work (use a watchdog or make the work idempotent), clock skew, and Redlock's contested safety guarantees. Where correctness is critical, prefer a database unique constraint or a real coordination service.` },
  { id: "sd19", c: "System Design", d: "Medium", q: `Design a multi-step onboarding/workflow engine.`, a: `Model it as a state machine persisted per entity: current state, allowed transitions, and an append-only event log for audit. Steps are declarative (config or JSON DSL) so business users can change ordering without a deploy. Requirements: resumability, idempotent step execution, timeouts and escalation, parallel branches, versioning so in-flight instances keep their original definition, and observability per step.`, t: `You have built a JSON DSL workflow engine — describe versioning of in-flight instances, it is the detail most candidates miss.` },
  { id: "sd20", c: "System Design", d: "Medium", q: `What is a circuit breaker and how does it work?`, a: `It tracks failures to a dependency; past a threshold it opens and fails calls immediately for a cooldown, then goes half-open to test with a few requests before closing. This stops a slow dependency from consuming all your workers and cascading the outage. Pair it with timeouts, bounded retries and a fallback (cached value, degraded feature, queued for later).` },
  { id: "sd21", c: "System Design", d: "Medium", q: `How do you estimate capacity in a design interview?`, a: `State assumptions out loud: DAU, actions per user per day, peak-to-average ratio (often 2-5x), read/write ratio, average payload size, retention period. Derive QPS = daily actions / 86400, peak QPS, storage per year, and bandwidth. Round to convenient numbers. The point is demonstrating that your architecture matches the order of magnitude, not arithmetic precision.` },
  { id: "sd22", c: "System Design", d: "Hard", q: `Design a system to export a very large report to the user.`, a: `Async job: request creates a job row and returns 202 with a job id. A worker streams the query in batches (cursor pagination, not offset), writes to a temporary file or directly to object storage in chunks, updates progress, then stores a presigned download URL with an expiry and notifies the user. Handle cancellation, job timeouts, retries with resume from checkpoint, and cleanup of expired artifacts.` },
  { id: "sd23", c: "System Design", d: "Medium", q: `How would you design an audit log?`, a: `Append-only, immutable records: who, what, when, from where, before/after values, request id, and the reason. Write it in the same transaction as the change or via an outbox so it cannot silently diverge. Store separately with restricted access and a retention policy, index for the queries auditors actually run (by actor, by entity, by time range), and never allow updates or deletes from application code.` },
  { id: "sd24", c: "System Design", d: "Medium", q: `How do you scale reads on a database?`, a: `Cache first (application cache, Redis, CDN for public data), then read replicas with a read preference, then denormalisation and precomputed views to remove expensive joins/aggregations, then sharding as a last resort. Watch replication lag — routing a read-after-write to a replica returns stale data, so route those to the primary or serve the local optimistic value.` },
  { id: "sd25", c: "System Design", d: "Medium", q: `Design an internal admin tool used by ~50 analysts daily.`, a: `Optimise for correctness, auditability and iteration speed over raw scale. Server-driven configuration so new fields and workflows do not need a release, role-based access with row-level scoping, full audit trail, bulk actions with dry-run and confirmation, saved filters, exports as async jobs, and strong observability of who is blocked. At that user count the bottleneck is queries and UX, not throughput.`, t: `This is essentially your Jarvis platform — be ready to describe it as a design.` },
  { id: "sd26", c: "System Design", d: "Hard", q: `How do you handle duplicate events in an at-least-once system?`, a: `Make consumers idempotent: use a natural or provided event id and record processed ids with a unique constraint or a TTL set in Redis, so a repeat is a no-op. Alternatively make the operation naturally idempotent (set a value rather than increment, upsert rather than insert). Also handle out-of-order arrival with a version or timestamp guard so an older event cannot overwrite a newer state.` },
  { id: "sd27", c: "System Design", d: "Medium", q: `What is the difference between latency and throughput, and how do you improve each?`, a: `Latency is time per request; throughput is requests per unit time. Reduce latency with caching, fewer round trips, closer edges, faster queries and less work per request. Increase throughput with concurrency, horizontal scaling, batching and async processing. They trade off: batching raises throughput while adding latency, which is fine for a pipeline and wrong for a login.` },
  { id: "sd28", c: "System Design", d: "Medium", q: `How do you design an API for a mobile client on a poor network?`, a: `Fewer, coarser endpoints that return everything a screen needs; compact payloads with only required fields; compression; pagination with small pages; ETags for conditional fetches; aggressive client caching with explicit staleness; offline queueing of mutations with idempotency keys; and generous but bounded timeouts with retry on idempotent calls only. Server-driven UI config reduces forced app updates.` },

  // ====================== BEHAVIOURAL & EXPERIENCE =========================
  { id: "bh1", c: "Behavioural", d: "Easy", q: `Walk me through your current project and your specific contribution.`, a: `Structure: what the product does and who uses it, why it matters to the business, the architecture in three sentences, then your ownership — what you designed, what you built, what you decided. End with a number (users, latency, error reduction, time saved). Say "I" for your work and "we" for the team's, and keep it under two minutes before pausing for questions.`, t: `Rehearse this out loud. It is asked in every interview and sets the tone for the whole conversation.` },
  { id: "bh2", c: "Behavioural", d: "Medium", q: `Tell me about the hardest technical problem you have solved.`, a: `Use STAR with a real debugging arc: the symptom, why the obvious explanation was wrong, how you narrowed it down (what you measured, what you eliminated), the actual root cause, the fix, and what you changed so it could not recur. The reasoning process is what is being assessed, not the difficulty of the bug.` },
  { id: "bh3", c: "Behavioural", d: "Medium", q: `Tell me about a time you disagreed with a senior engineer or your manager.`, a: `Show that you disagreed with data and committed to the outcome. Structure: the decision, your concern and the evidence you brought, how you raised it (privately, with an alternative proposal), what was decided, and how you supported it afterwards. Avoid stories where you were right and everyone else was foolish.` },
  { id: "bh4", c: "Behavioural", d: "Medium", q: `Tell me about a production incident you caused or handled.`, a: `Own it plainly. What broke, how it was detected (and whether detection was fast enough), how you mitigated it first and diagnosed second, the root cause, and the systemic fix — a test, an alert, a guardrail. Blaming a process without owning your part reads badly; so does self-flagellation. Blameless and specific is the register.` },
  { id: "bh5", c: "Behavioural", d: "Medium", q: `Why are you leaving your current role?`, a: `Frame forward, not backward: what you want next — larger scale, deeper ownership of a product area, stronger engineering practices, a specific domain. One honest sentence about what your current role cannot offer is fine; criticising your employer or teammates is not. Make it consistent with the role you are applying for.` },
  { id: "bh6", c: "Behavioural", d: "Medium", q: `How do you handle a tight deadline with unclear requirements?`, a: `Clarify the actual outcome and the non-negotiables, propose a scoped version that delivers the core value, make the trade-off explicit in writing, and flag risk early rather than at the deadline. Give an example where you cut scope rather than quality, and what you deliberately deferred with a follow-up ticket.` },
  { id: "bh7", c: "Behavioural", d: "Medium", q: `Tell me about a time you improved something nobody asked you to.`, a: `Good territory: adding tests to an untested critical path, cutting build or deploy time, fixing a recurring on-call annoyance, improving a slow page. Say what the cost was before, what you changed, and the measured result. Also mention how you got buy-in — unilateral refactors are a yellow flag.` },
  { id: "bh8", c: "Behavioural", d: "Medium", q: `How do you approach code review?`, a: `As an author: small PRs, a description explaining why not just what, self-review first, tests included. As a reviewer: separate blocking issues from preferences, ask questions rather than issue verdicts, focus on correctness, security and maintainability over style (that is the linter's job), and approve rather than nitpicking indefinitely. Cite an example where a review caught something real.` },
  { id: "bh9", c: "Behavioural", d: "Medium", q: `How do you keep learning, and what have you learned recently?`, a: `Be concrete and recent: one thing you learned, how you learned it, and where you applied it. Vague answers about "reading blogs and docs" land flat. Mention a source you actually follow and something you built to understand a concept properly.` },
  { id: "bh10", c: "Behavioural", d: "Medium", q: `Describe a time you had to say no or push back on scope.`, a: `Show judgement, not obstinacy: the request, the cost you identified, the alternative you offered, and the outcome. The strongest version ends with the stakeholder agreeing because you framed the trade-off in their terms — timeline, risk, or maintenance cost — rather than in technical purity.` },
  { id: "bh11", c: "Behavioural", d: "Medium", q: `What is your biggest weakness?`, a: `Pick something real, bounded and improving, with the concrete mechanism you use to manage it — for example, going deep on a problem past the point of value, so you now timebox investigations and check in early. Avoid disguised strengths and avoid anything that disqualifies you for the role.` },
  { id: "bh12", c: "Behavioural", d: "Medium", q: `Tell me about a time you mentored or unblocked someone.`, a: `Even at 2 years you have examples: onboarding a new joiner, writing documentation for a confusing subsystem, interviewing candidates, or pairing through a bug. Describe what they were stuck on, what you did (asked questions rather than took over), and the result. This signals readiness for scope beyond your own tickets.` },
  { id: "bh13", c: "Behavioural", d: "Medium", q: `How do you prioritise when everything is urgent?`, a: `Separate real urgency from stated urgency: user impact, revenue or compliance risk, blocked colleagues, reversibility. Communicate what you are doing first and what is waiting, and get explicit agreement rather than silently dropping something. Give an example where you renegotiated rather than burned a weekend.` },
  { id: "bh14", c: "Behavioural", d: "Medium", q: `Where do you see yourself in 3 years?`, a: `Show direction without sounding like you will leave in six months: deeper technical ownership, leading a feature area end to end, mentoring, and stronger system design skill. Tie it to something the company plausibly offers. "Manager" is a fine answer only if the role has that path.` },
  { id: "bh15", c: "Behavioural", d: "Medium", q: `What questions do you have for us?`, a: `Ask things that reveal how the team really works: how features go from idea to production, what the on-call and incident culture is, how technical debt gets prioritised, what the review and release cadence is, what success looks like at 6 months, and why the last person in this role left. Having no questions reads as low interest.` },
  { id: "bh16", c: "Behavioural", d: "Medium", q: `How do you explain a technical trade-off to a non-technical stakeholder?`, a: `Lead with the business outcome and the options in their language — time, cost, risk, user impact — then give a recommendation with a reason, and only go into mechanics if asked. Practise on your own project: describe why you chose your caching or data model in two sentences with no jargon.` },
  { id: "bh17", c: "Behavioural", d: "Medium", q: `Tell me about a time you shipped something with known technical debt.`, a: `Show deliberate decision-making: what you cut, why the deadline justified it, how you contained the risk (feature flag, isolated module, monitoring), how you documented it, and whether it was actually paid back. Debt taken knowingly and tracked is engineering; debt taken by accident is carelessness.` },
  { id: "bh18", c: "Behavioural", d: "Medium", q: `Why should we hire you for this role?`, a: `Map two or three of their stated needs directly to things you have done, with evidence, and add what you would want to learn there. Specific beats enthusiastic: "you need someone who owns a React and Node product end to end, and I have run one used daily by 50 people including its Android build and release pipeline" is a stronger sentence than any adjective.` },
];

// ---------------------------------------------------------------------------
// APP
// ---------------------------------------------------------------------------

const C = {
  ink: "#16181D",
  ink2: "#4A505E",
  ink3: "#7C8493",
  paper: "#EFF0F3",
  surface: "#FFFFFF",
  line: "#DDDFE6",
  accent: "#3B2FB5",
  accentSoft: "#EDEBFA",
};

const STATUSES = [
  { key: "unread", label: "Not started", short: "New", color: "#B7BCC7" },
  { key: "learning", label: "Learning", short: "Learning", color: "#2F6BE0" },
  { key: "revise", label: "Revise", short: "Revise", color: "#D97706" },
  { key: "known", label: "Confident", short: "Confident", color: "#0E7C66" },
];

const STATUS_MAP = Object.fromEntries(STATUSES.map((s) => [s.key, s]));
const DIFFS = ["Easy", "Medium", "Hard"];
const DIFF_COLOR = { Easy: "#0E7C66", Medium: "#B45309", Hard: "#B02A37" };
const STORAGE_KEY = "mern-interview-bank-v1";

const CATEGORIES = QUESTIONS.reduce((acc, q) => {
  if (!acc.includes(q.c)) acc.push(q.c);
  return acc;
}, []);

function ReadinessMeter({ questions, statusOf }) {
  return (
    <div className="flex w-full gap-px overflow-hidden rounded" style={{ height: 22 }}>
      {questions.map((q) => (
        <div
          key={q.id}
          title={q.c}
          className="flex-1"
          style={{ backgroundColor: STATUS_MAP[statusOf(q.id)].color, minWidth: 1 }}
        />
      ))}
    </div>
  );
}

function Bar({ value, total, color }) {
  const pct = total ? Math.round((value / total) * 100) : 0;
  return (
    <div className="h-1 w-full overflow-hidden rounded-full" style={{ backgroundColor: C.line }}>
      <div className="h-full" style={{ width: pct + "%", backgroundColor: color }} />
    </div>
  );
}

function QuestionCard({ q, index, status, onStatus, expanded, onToggle, starred, onStar }) {
  const s = STATUS_MAP[status];
  return (
    <div
      className="mb-2 rounded-lg border"
      style={{ borderColor: expanded ? C.accent : C.line, backgroundColor: C.surface }}
    >
      <div className="flex items-start gap-3 p-3 sm:p-4">
        <div
          className="mt-1 shrink-0 rounded-sm"
          style={{ width: 4, height: 34, backgroundColor: s.color }}
        />
        <button
          onClick={onToggle}
          className="flex-1 text-left"
          style={{ color: C.ink }}
          aria-expanded={expanded}
        >
          <div className="mb-1 flex flex-wrap items-center gap-2" style={{ fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace", fontSize: 10, letterSpacing: "0.08em" }}>
            <span style={{ color: C.ink3 }}>{String(index + 1).padStart(3, "0")}</span>
            <span style={{ color: C.ink3 }}>{q.c.toUpperCase()}</span>
            <span style={{ color: DIFF_COLOR[q.d] }}>{q.d.toUpperCase()}</span>
            {q.t && <span style={{ color: C.accent }}>TIP</span>}
          </div>
          <div className="text-[15px] font-semibold leading-snug sm:text-base">{q.q}</div>
        </button>
        <button
          onClick={onStar}
          aria-label={starred ? "Remove flag" : "Flag this question"}
          className="shrink-0 px-1 text-lg leading-none"
          style={{ color: starred ? "#D97706" : C.line }}
        >
          {starred ? "\u2605" : "\u2606"}
        </button>
      </div>

      {expanded && (
        <div className="px-3 pb-3 sm:px-4 sm:pb-4">
          <div
            className="rounded-md p-3 text-sm leading-relaxed sm:p-4"
            style={{ backgroundColor: C.paper, color: C.ink2 }}
          >
            {q.a}
            {q.t && (
              <div
                className="mt-3 border-l-2 pl-3 text-[13px]"
                style={{ borderColor: C.accent, color: C.accent }}
              >
                {q.t}
              </div>
            )}
          </div>
          <div className="mt-3 flex flex-wrap gap-1.5">
            {STATUSES.map((opt) => {
              const active = opt.key === status;
              return (
                <button
                  key={opt.key}
                  onClick={() => onStatus(opt.key)}
                  className="rounded-full border px-3 py-1 text-xs font-medium"
                  style={{
                    borderColor: active ? opt.color : C.line,
                    backgroundColor: active ? opt.color : "transparent",
                    color: active ? "#fff" : C.ink2,
                  }}
                >
                  {opt.label}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default function MernInterviewBank() {
  const [state, setState] = useState({ status: {}, starred: {} });
  const [loaded, setLoaded] = useState(false);
  const [category, setCategory] = useState("All");
  const [diff, setDiff] = useState("All");
  const [statusFilter, setStatusFilter] = useState("All");
  const [query, setQuery] = useState("");
  const [onlyStarred, setOnlyStarred] = useState(false);
  const [expanded, setExpanded] = useState({});
  const [drill, setDrill] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const res = await window.storage.get(STORAGE_KEY);
        if (res && res.value) {
          const parsed = JSON.parse(res.value);
          setState({ status: parsed.status || {}, starred: parsed.starred || {} });
        }
      } catch (e) {
        // No saved progress yet — start fresh.
      }
      setLoaded(true);
    })();
  }, []);

  const persist = useCallback(async (next) => {
    try {
      await window.storage.set(STORAGE_KEY, JSON.stringify(next));
    } catch (e) {
      console.error("Could not save progress", e);
    }
  }, []);

  const statusOf = useCallback((id) => state.status[id] || "unread", [state.status]);

  const setStatus = (id, value) => {
    setState((prev) => {
      const next = { ...prev, status: { ...prev.status, [id]: value } };
      persist(next);
      return next;
    });
  };

  const toggleStar = (id) => {
    setState((prev) => {
      const starred = { ...prev.starred };
      if (starred[id]) delete starred[id];
      else starred[id] = true;
      const next = { ...prev, starred };
      persist(next);
      return next;
    });
  };

  const counts = useMemo(() => {
    const base = { unread: 0, learning: 0, revise: 0, known: 0 };
    QUESTIONS.forEach((q) => { base[statusOf(q.id)] += 1; });
    return base;
  }, [statusOf]);

  const perCategory = useMemo(() => {
    const map = {};
    CATEGORIES.forEach((c) => { map[c] = { total: 0, known: 0 }; });
    QUESTIONS.forEach((q) => {
      map[q.c].total += 1;
      if (statusOf(q.id) === "known") map[q.c].known += 1;
    });
    return map;
  }, [statusOf]);

  const filtered = useMemo(() => {
    const term = query.trim().toLowerCase();
    let list = QUESTIONS.filter((q) => {
      if (category !== "All" && q.c !== category) return false;
      if (diff !== "All" && q.d !== diff) return false;
      if (statusFilter !== "All" && statusOf(q.id) !== statusFilter) return false;
      if (onlyStarred && !state.starred[q.id]) return false;
      if (term && !(q.q + " " + q.a + " " + q.c).toLowerCase().includes(term)) return false;
      return true;
    });
    if (drill) list = list.filter((q) => drill.includes(q.id));
    return list;
  }, [category, diff, statusFilter, query, onlyStarred, statusOf, state.starred, drill]);

  const startDrill = () => {
    const pool = QUESTIONS.filter((q) => statusOf(q.id) !== "known");
    const picked = [...pool].sort(() => Math.random() - 0.5).slice(0, 10).map((q) => q.id);
    setDrill(picked);
    setCategory("All"); setDiff("All"); setStatusFilter("All");
    setQuery(""); setOnlyStarred(false); setExpanded({});
  };

  const resetAll = async () => {
    const next = { status: {}, starred: {} };
    setState(next);
    await persist(next);
  };

  const total = QUESTIONS.length;
  const readiness = Math.round(((counts.known + counts.learning * 0.4 + counts.revise * 0.2) / total) * 100);

  const chip = (active) => ({
    borderColor: active ? C.accent : C.line,
    backgroundColor: active ? C.accent : C.surface,
    color: active ? "#fff" : C.ink2,
  });

  if (!loaded) {
    return (
      <div className="flex h-64 items-center justify-center text-sm" style={{ color: C.ink3 }}>
        Loading your progress...
      </div>
    );
  }


  return (
    <div className="min-h-screen w-full" style={{ backgroundColor: C.paper, color: C.ink }}>
      <div className="mx-auto max-w-6xl px-3 py-5 sm:px-6 sm:py-8">

        {/* Header */}
        <header className="mb-5">
          <div
            className="mb-1"
            style={{ fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace", fontSize: 11, letterSpacing: "0.18em", color: C.accent }}
          >
            SDE · 2+ YEARS · MERN
          </div>
          <h1 className="text-2xl font-black leading-none tracking-tight sm:text-4xl">
            Interview question bank
          </h1>
          <p className="mt-2 max-w-2xl text-sm" style={{ color: C.ink2 }}>
            {total} questions across React, Node, Express, MongoDB, security, deployment and system
            design. Open a question, answer it out loud first, then read the model answer and mark
            where you stand.
          </p>
        </header>

        {/* Readiness */}
        <section
          className="mb-5 rounded-xl border p-4"
          style={{ backgroundColor: C.surface, borderColor: C.line }}
        >
          <div className="mb-3 flex flex-wrap items-baseline justify-between gap-2">
            <div className="flex items-baseline gap-2">
              <span className="text-3xl font-black tabular-nums">{readiness}%</span>
              <span className="text-sm" style={{ color: C.ink3 }}>ready</span>
            </div>
            <div className="flex flex-wrap gap-3 text-xs" style={{ color: C.ink2 }}>
              {STATUSES.map((s) => (
                <span key={s.key} className="flex items-center gap-1.5">
                  <span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ backgroundColor: s.color }} />
                  {s.label} <b className="tabular-nums">{counts[s.key]}</b>
                </span>
              ))}
            </div>
          </div>
          <ReadinessMeter questions={QUESTIONS} statusOf={statusOf} />
          <div className="mt-2 text-[11px]" style={{ color: C.ink3 }}>
            One tick per question, in bank order. Confident answers count fully, learning and revise
            count partially.
          </div>
        </section>

        <div className="gap-5 lg:flex">
          {/* Sidebar */}
          <aside className="mb-5 lg:mb-0 lg:w-64 lg:shrink-0">
            <div className="rounded-xl border p-2" style={{ backgroundColor: C.surface, borderColor: C.line }}>
              <button
                onClick={() => { setCategory("All"); setDrill(null); }}
                className="mb-1 w-full rounded-lg px-3 py-2 text-left text-sm font-semibold"
                style={{
                  backgroundColor: category === "All" ? C.accentSoft : "transparent",
                  color: category === "All" ? C.accent : C.ink,
                }}
              >
                All categories <span className="tabular-nums" style={{ color: C.ink3 }}>{total}</span>
              </button>
              {CATEGORIES.map((c) => {
                const active = category === c;
                const pc = perCategory[c];
                return (
                  <button
                    key={c}
                    onClick={() => { setCategory(c); setDrill(null); }}
                    className="mb-1 w-full rounded-lg px-3 py-2 text-left"
                    style={{ backgroundColor: active ? C.accentSoft : "transparent" }}
                  >
                    <div className="flex items-center justify-between text-sm font-medium" style={{ color: active ? C.accent : C.ink }}>
                      <span>{c}</span>
                      <span className="tabular-nums text-xs" style={{ color: C.ink3 }}>
                        {pc.known}/{pc.total}
                      </span>
                    </div>
                    <div className="mt-1.5">
                      <Bar value={pc.known} total={pc.total} color={active ? C.accent : "#0E7C66"} />
                    </div>
                  </button>
                );
              })}
            </div>

            <button
              onClick={startDrill}
              className="mt-3 w-full rounded-lg px-3 py-2.5 text-sm font-semibold"
              style={{ backgroundColor: C.accent, color: "#fff" }}
            >
              Drill 10 random questions
            </button>
            <button
              onClick={resetAll}
              className="mt-2 w-full rounded-lg border px-3 py-2 text-xs"
              style={{ borderColor: C.line, color: C.ink3, backgroundColor: C.surface }}
            >
              Clear all progress
            </button>
          </aside>

          {/* Main */}
          <main className="min-w-0 flex-1">
            <div
              className="mb-4 rounded-xl border p-3"
              style={{ backgroundColor: C.surface, borderColor: C.line }}
            >
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Search questions and answers"
                className="mb-3 w-full rounded-lg border px-3 py-2 text-sm outline-none"
                style={{ borderColor: C.line, color: C.ink }}
              />
              <div className="flex flex-wrap items-center gap-1.5">
                <button onClick={() => setDiff("All")} className="rounded-full border px-3 py-1 text-xs font-medium" style={chip(diff === "All")}>
                  Any level
                </button>
                {DIFFS.map((d) => (
                  <button key={d} onClick={() => setDiff(d)} className="rounded-full border px-3 py-1 text-xs font-medium" style={chip(diff === d)}>
                    {d}
                  </button>
                ))}
                <span className="mx-1 hidden h-4 w-px sm:inline-block" style={{ backgroundColor: C.line }} />
                <button onClick={() => setStatusFilter("All")} className="rounded-full border px-3 py-1 text-xs font-medium" style={chip(statusFilter === "All")}>
                  Any status
                </button>
                {STATUSES.map((s) => (
                  <button key={s.key} onClick={() => setStatusFilter(s.key)} className="rounded-full border px-3 py-1 text-xs font-medium" style={chip(statusFilter === s.key)}>
                    {s.short}
                  </button>
                ))}
                <button onClick={() => setOnlyStarred(!onlyStarred)} className="rounded-full border px-3 py-1 text-xs font-medium" style={chip(onlyStarred)}>
                  {"\u2605"} Flagged
                </button>
              </div>
            </div>

            <div className="mb-3 flex flex-wrap items-center justify-between gap-2 text-xs" style={{ color: C.ink3 }}>
              <span>
                Showing <b className="tabular-nums" style={{ color: C.ink }}>{filtered.length}</b> of {total}
                {drill && " · drill set"}
              </span>
              <span className="flex gap-3">
                {drill && (
                  <button onClick={() => setDrill(null)} style={{ color: C.accent }}>Exit drill</button>
                )}
                <button
                  onClick={() => {
                    const all = {};
                    filtered.forEach((q) => { all[q.id] = true; });
                    setExpanded(all);
                  }}
                  style={{ color: C.accent }}
                >
                  Reveal all
                </button>
                <button onClick={() => setExpanded({})} style={{ color: C.accent }}>Collapse all</button>
              </span>
            </div>

            {filtered.length === 0 ? (
              <div
                className="rounded-xl border p-8 text-center text-sm"
                style={{ backgroundColor: C.surface, borderColor: C.line, color: C.ink2 }}
              >
                Nothing matches these filters. Clear the search or pick another category to keep going.
              </div>
            ) : (
              filtered.map((q, i) => (
                <QuestionCard
                  key={q.id}
                  q={q}
                  index={i}
                  status={statusOf(q.id)}
                  starred={!!state.starred[q.id]}
                  onStar={() => toggleStar(q.id)}
                  onStatus={(v) => setStatus(q.id, v)}
                  expanded={!!expanded[q.id]}
                  onToggle={() => setExpanded((p) => ({ ...p, [q.id]: !p[q.id] }))}
                />
              ))
            )}

            <footer className="mt-6 text-[11px] leading-relaxed" style={{ color: C.ink3 }}>
              Progress saves automatically. Study order that works: mark everything you can already
              answer as Confident, then work Revise and Not started by category, and use the drill
              button the day before an interview.
            </footer>
          </main>
        </div>
      </div>
    </div>
  );
}
